<style>
  /* ================= 1920 年代悬疑推理双主题系统 ================= */
  :root, body.theme-arcane {
    --noir-bg: #05070c;
    --amber: #d9b45c;
    --amber-dim: rgba(198, 161, 84, 0.55);
