  /* ---- 按钮 ---- */
  .btn-noir { display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem;
    padding: 0.62rem 1.7rem; border: 1px solid var(--btn-border); color: var(--accent); cursor: pointer;
