    transition: all 0.3s ease; }
  .fs-btn:hover { background: rgba(198, 161, 84, 0.24); box-shadow: 0 0 16px var(--amber-glow); border-color: var(--amber); color: #e6cf9a; }
  .fs-btn svg { width: 18px; height: 18px; }

  /* ---- 卡片（技能/物品/立绘可选卡） ---- */
  .card { border: 1px solid var(--slot-border); border-radius: 8px; cursor: pointer;
    background: var(--slot-bg); transition: all 0.3s ease; }
  .card:hover { border-color: var(--panel-border-bright); background: var(--card-hover); }
  .card.sel { border-color: var(--accent); box-shadow: 0 0 16px var(--accent-glow), inset 0 0 10px rgba(198, 161, 84, 0.08);
    background: rgba(34, 30, 16, 0.65); }

  /* 大尺寸角色立绘展台（破框沉浸，去除狭窄黑框留白，与右侧等高对齐） */
  .portrait-podium {
    position: relative; width: 100%; min-height: 520px; height: 100%;
    display: flex; flex-direction: column; justify-content: space-between;
