  .voice-bar { width: 3px; height: 100%; background-color: var(--accent); border-radius: 2px;
    animation: wave-bar 0.8s ease-in-out infinite alternate; }
  .voice-bar:nth-child(1) { animation-delay: 0.1s; height: 35%; }
  .voice-bar:nth-child(2) { animation-delay: 0.3s; height: 75%; }
  .voice-bar:nth-child(3) { animation-delay: 0.15s; height: 100%; }
  .voice-bar:nth-child(4) { animation-delay: 0.4s; height: 60%; }
  .voice-bar:nth-child(5) { animation-delay: 0.25s; height: 40%; }
  @keyframes wave-bar { 0% { transform: scaleY(0.25); } 100% { transform: scaleY(1); } }
  .voice-wave.paused .voice-bar { animation-play-state: paused; transform: scaleY(0.3); }

  /* 技能插槽阶梯式滑入芯片（demo 移植：现代过渡动效 + 主题化样式） */
  .skill-slot-chip {
    background: var(--slot-bg); border: 1px solid var(--slot-border);
    border-radius: 8px; padding: 6px 12px; display: flex; align-items: center;
    justify-content: space-between; gap: 10px; transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
    position: relative; overflow: hidden; animation: slot-slide-in 0.32s cubic-bezier(0.16, 1, 0.3, 1) both;
    animation-delay: calc(var(--slot-idx, 0) * 0.04s);
  }
  @keyframes slot-slide-in { 0% { opacity: 0; transform: translateY(10px); } 100% { opacity: 1; transform: translateY(0); } }
  /* 技能列表按各职业最坏高度预留：切换职业时右栏外框高度恒定不跳动 */
  #hero-skill-chips-container { min-height: 335px; }
  /* 自定义角色两步同款预留：6 槽芯片随效果胶囊换行数变化，按最坏高度恒定外框 */
  #c3-limited-slots-container { min-height: 250px; }
  #c3-equipped-slots-grid { min-height: 250px; }
  .skill-slot-chip:before {
    content: ''; position: absolute; top: 0; left: 0; bottom: 0; width: 3px;
    background: var(--slot-border); transition: background 0.25s ease;
