  .skill-slot-chip.type-generic:before { background: #c084fc; box-shadow: 0 0 10px rgba(192, 132, 252, 0.5); }
  /* 威廉专属技能芯片：纯金流光镶边 + 密教金辉全光晕 (Gilded Arcane) */
  .skill-slot-chip.theme-gold:before,
  .skill-slot-chip.type-limited:before {
    background: linear-gradient(to bottom, #fbbf24 0%, #d9b45c 50%, #92400e 100%);
    box-shadow: 0 0 12px rgba(217, 180, 92, 0.75), 0 0 6px rgba(251, 191, 36, 0.5);
  }
  .skill-slot-chip.theme-gold {
    border-color: rgba(217, 180, 92, 0.32);
    background: linear-gradient(90deg, rgba(217, 180, 92, 0.06) 0%, rgba(26, 20, 14, 0.55) 22%, rgba(15, 12, 10, 0.78) 100%);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.55), 0 0 10px rgba(217, 180, 92, 0.12);
