  }
  .skill-slot-chip.theme-purple {
    border-color: rgba(217, 180, 92, 0.28);
    background: linear-gradient(90deg, rgba(217, 180, 92, 0.05) 0%, rgba(28, 18, 45, 0.55) 22%, rgba(16, 12, 28, 0.75) 100%);
