    position: relative; overflow: hidden; display: flex; flex-direction: column; justify-content: space-between;
  }
  .class-tab-card:hover { border-color: var(--panel-border-bright); background: var(--card-hover); transform: translateY(-2px); }
  .class-tab-card.active { border-color: var(--accent); background: linear-gradient(150deg, var(--card-hover), var(--accent-dim)); box-shadow: 0 0 20px var(--accent-glow); }
  .class-tab-card.active:before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent); box-shadow: 0 0 8px var(--accent); }

  /* 技能备选卡片（购点） */
  .skill-pick-card {
