  }
  .stage-fade-in {
    opacity: 1 !important; transform: translateY(0) scale(1) !important;
    transition: opacity 0.3s cubic-bezier(0.16, 1, 0.3, 1), transform 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;
  }

  /* ===== 幕布式转场覆盖层（源自 demo-transition-preview.html）：百叶快落 / 浓雾涌漫 ===== */
  /* 时序由 JS 状态机驱动：is-closing（合拢）→ is-closed（全闭钉住，换内容）→ is-opening（散开） */
  .fx-ov { position: fixed; inset: 0; z-index: 9999; overflow: hidden; pointer-events: none; display: none; }
  .fx-ov.is-closing, .fx-ov.is-closed, .fx-ov.is-opening { pointer-events: auto; }

  /* —— 百叶快落：14 片影棚竖百叶依次拍落，反向斜收 + 冷光扫线 —— */
  .fx-blind .b-slat {
    position: absolute; top: 0; bottom: 0; width: calc(100% / 14 + 1px);
    left: calc(var(--i) * 100% / 14);
    background: linear-gradient(180deg, #3c3c40, #232327 58%, #151518);
    box-shadow: inset 1px 0 rgba(255,255,255,.07), inset -1px 0 rgba(0,0,0,.55), inset 0 0 24px rgba(0,0,0,.35);
    transform: scaleY(0); transform-origin: top;
  }
  .fx-blind .b-slat:nth-child(odd) { filter: brightness(1.06); }
  .fx-blind.is-closing .b-slat, .fx-blind.is-closed .b-slat {
    transform: scaleY(1);
    transition: transform 240ms cubic-bezier(.6,.05,.3,1);
    transition-delay: calc(var(--i) * 42ms);
  }
  .fx-blind.is-opening .b-slat {
    transform: scaleY(0); transform-origin: bottom;
    transition: transform 240ms cubic-bezier(.6,.05,.3,1);
    transition-delay: calc((13 - var(--i)) * 42ms);
  }
  .fx-blind .b-sheen {
    position: absolute; inset: 0; z-index: 2; opacity: 0;
    background: linear-gradient(105deg, transparent 30%, rgba(226,222,212,.14) 46%, rgba(226,222,212,.03) 54%, transparent 70%);
  }
  .fx-blind.is-closed .b-sheen { animation: fx-blind-sheen 900ms ease .15s both; }
  @keyframes fx-blind-sheen { 0% { opacity: 0; transform: translateX(-30%); } 30% { opacity: 1; } 100% { opacity: 0; transform: translateX(30%); } }

  /* —— 浓雾涌漫：八团雾自两侧涌入漫满全屏，继续漂远散去 —— */
  .fx-fog .f-base {
    position: absolute; inset: -10%;
    background:
      radial-gradient(120% 90% at 12% 88%, rgba(214,212,206,.95), transparent 55%),
      radial-gradient(110% 85% at 88% 20%, rgba(206,204,198,.92), transparent 58%),
      linear-gradient(120deg, rgba(198,196,190,.55), rgba(222,220,214,.66));
    opacity: 0;
  }
  .fx-fog.is-closing .f-base, .fx-fog.is-closed .f-base { opacity: 1; transition: opacity 900ms ease; }
  .fx-fog.is-opening .f-base { opacity: 0; transition: opacity 1050ms ease; }
  .fx-fog .f-blob {
    position: absolute; left: var(--x); top: var(--y);
    width: 46%; aspect-ratio: 1; border-radius: 50%;
    background: radial-gradient(circle, rgba(224,222,216,.94) 0%, rgba(214,212,206,.55) 42%, rgba(210,208,202,0) 72%);
    filter: blur(26px);
    opacity: 0;
    transform: translate(var(--dx), var(--dy)) scale(var(--s, 1));
  }
  .fx-fog.is-closing .f-blob, .fx-fog.is-closed .f-blob {
    opacity: 1;
    transform: translate(0, 0) scale(var(--s, 1));
    transition: transform 1050ms cubic-bezier(.4,.1,.35,.96), opacity 800ms ease;
  }
  .fx-fog.is-opening .f-blob {
    opacity: 0;
    transform: translate(calc(var(--dx) * 2.3), calc(var(--dy) * 2.3)) scale(calc(var(--s, 1) * 1.25));
    transition: transform 1150ms cubic-bezier(.45,.05,.4,.95), opacity 950ms ease .1s;
  }
  .fx-fog.is-closed .f-base { animation: fx-fog-drift 7s ease-in-out infinite alternate; }
  @keyframes fx-fog-drift { from { background-position: 0% 0%, 100% 100%, 0 0; } to { background-position: 6% 3%, 94% 96%, 3% 2%; } }

  /* 插槽增量插入轻柔弹入动效 */
  .slot-chip-pop { animation: slot-pop 0.32s cubic-bezier(0.16, 1, 0.3, 1) both; }
  @keyframes slot-pop { 0% { opacity: 0; transform: scale(0.94) translateY(6px); } 100% { opacity: 1; transform: scale(1) translateY(0); } }

  /* 局部文字与属性平滑过渡 */
  .smooth-fade-transition { transition: opacity 0.22s ease, transform 0.22s ease; }
  .view-transition-in { animation: view-in 0.4s cubic-bezier(0.16, 1, 0.3, 1) both; }
  @keyframes view-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

  /* ---- 标题旧放映机闪烁 ---- */
  .flicker { animation: flicker 4.2s linear infinite; }
  @keyframes flicker {
    0%, 100% { opacity: 1; } 3% { opacity: 0.72; } 5% { opacity: 1; } 42% { opacity: 1; }
    44% { opacity: 0.82; } 46% { opacity: 1; } 78% { opacity: 0.9; } 80% { opacity: 1; } }

  /* ---- 打字机光标 ---- */
  .tw-caret::after { content: '▌'; color: var(--amber); animation: caret 0.9s steps(1) infinite; }
  @keyframes caret { 50% { opacity: 0; } }

  /* ---- 立绘投影（半透明浮动 + 底部渐隐） ---- */
  .holo-wrap { position: relative; }
  .holo { animation: holo-float 5.5s ease-in-out infinite;
    -webkit-mask-image: linear-gradient(to bottom, black 78%, transparent 100%);
    mask-image: linear-gradient(to bottom, black 78%, transparent 100%); }
  @keyframes holo-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-12px); } }
  .holo-ph { display: flex; align-items: center; justify-content: center; }

  /* ---- 档案纸（确认页） ---- */
  .paper { background: linear-gradient(168deg, var(--paper-hi), var(--paper-lo));
    color: var(--ink); border: 1px solid #b7a77f; border-radius: 3px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6), inset 0 0 40px rgba(120, 96, 48, 0.14);
    transform: rotate(-0.4deg); }
  .paper .tw-line { border-bottom: 1px dashed rgba(44, 36, 22, 0.35); }
  .stamp { display: inline-block; padding: 0.2rem 0.8rem; border: 3px double #a03030; color: #a03030;
    font-weight: 900; letter-spacing: 0.3em; transform: rotate(-8deg); opacity: 0.85; border-radius: 4px; }

  /* ---- 过场 ---- */
  .fade-in { animation: fade-in 0.55s ease both; }
  @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
  .flash-warn { color: #d98c8c; font-size: 0.82rem; letter-spacing: 0.08em; }

  /* ---- 进度条 ---- */
  .progress-track { height: 3px; background: rgba(198, 161, 84, 0.15); border-radius: 2px; overflow: hidden; }
  .progress-fill { height: 100%; background: linear-gradient(90deg, rgba(198, 161, 84, 0.5), var(--amber));
    box-shadow: 0 0 10px var(--amber-glow); transition: width 0.45s ease; }

  * { -webkit-tap-highlight-color: transparent; }
