    animation: p-drift var(--p-dur, 12s) ease-in-out infinite var(--p-del, 0s);
  }
  @keyframes p-drift {
    0% { opacity: 0; transform: translate(0, 0) scale(0.7); }
    20% { opacity: var(--p-op, 0.5); }
    75% { opacity: var(--p-op, 0.5); }
    100% { opacity: 0; transform: translate(var(--p-tx, 10px), var(--p-ty, -70px)) scale(1.2); }
  }

  /* ===== demo 移植：现代微晶品阶流光徽章 ===== */
  .tier-badge-modern-adv {
    border: 1px solid rgba(251, 191, 36, 0.55);
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.22), rgba(120, 53, 15, 0.35));
    color: #fef08a; box-shadow: 0 0 10px rgba(245, 158, 11, 0.25);
  }
  .tier-badge-modern-leg {
    border: 1px solid rgba(248, 113, 113, 0.65);
    background: linear-gradient(135deg, rgba(220, 38, 38, 0.28), rgba(136, 19, 55, 0.45));
    color: #fee2e2; box-shadow: 0 0 12px rgba(239, 68, 68, 0.38);
  }

  /* ===== demo 移植：左侧展台专属实机战斗视窗（hover 职业卡弹出，移开收起） ===== */
  .stage-combat-monitor {
