  /* ===== demo 移植：技能机制胶囊悬停触发态 ===== */
  .pill-trigger { cursor: help; transition: all 0.18s ease; }
  .pill-trigger:hover { border-color: var(--accent); background: rgba(255, 255, 255, 0.08); transform: scale(1.04); }

  /* ===== demo 移植：纯悬浮窗（Floating Tooltip）核心体系 ===== */
