  const SLOT_NAMES = ['单体', '群攻', '穿透', '群穿透', '散射', '群散射', '眩晕', '群眩晕', '单降', '群降', '单盲', '群盲', '单滞', '群滞', '单弱', '群弱', '中毒', '群中毒', '燃烧', '群燃烧', '麻痹', '群麻痹', '吸蓝', '单增', '群增', '单防', '群防', '单速', '群速', '单回', '群回', '单盾', '群盾', '单回蓝', '群回蓝', '单冲', '群冲', '单瞄', '群瞄', '嘲讽', '反击', '群反击', '再动', '回避', '群避', '单避', '免伤', '自盲', '自降', '自弱', '自滞', '自缓', '驱散', '群驱散'];
  function parseSkillLine(raw, entry) {
    const nm = raw.match(/【([^】]+)】/);
