          entry.data[slot === 1 ? 'power' : 'power' + slot] = parseInt(m[2], 10);
        }
        continue;
      }
      if ((m = t.match(/^(MP|HP|TP)\s*[:：]\s*(\d+)$/i))) {
        const v = parseInt(m[2], 10);
        if (m[1].toUpperCase() === 'MP') entry.data.cost = v;
        else if (m[1].toUpperCase() === 'HP') entry.data.hpCost = v;
        else entry.data.tpCost = v;
        continue;
      }
      if ((m = t.match(/^延迟\s*[:：]\s*(\d+)$/))) { entry.data.delay = parseInt(m[1], 10); continue; }
      if ((m = t.match(/^加速\s*[:：]\s*(\d+)$/))) { entry.data.haste = parseInt(m[1], 10); continue; }
      if ((m = t.match(/^限(\d+)次$/))) { entry.data.maxUses = parseInt(m[1], 10); continue; }
      if ((m = t.match(/^(?:Hit|Aim)\s*[:：]\s*(\d+)$/i))) { entry.data.hit = parseInt(m[1], 10); continue; }
      if ((m = t.match(/^(?:Turns?|持续|回)\s*[:：]\s*(\d+)$/i))) { entry.data.turns = parseInt(m[1], 10); continue; }
      if ((m = t.match(/^暴击\s*[:：]\s*(\d+)\s*%?$/))) { entry.data.critRate = Math.max(0, Math.min(100, parseInt(m[1], 10))); continue; }
      if ((m = t.match(/^反应(?:\s*[:：]\s*(近战|远程|法术))?\s*$/))) { entry.data.isReaction = true; entry.data.reactionTarget = m[1] || 'all'; continue; }
      if ((m = t.match(/^看破(?:\s*[:：]\s*(近战|远程|法术|all))?\s*$/))) { entry.data.kanpoTarget = m[1] || 'all'; continue; }
      if ((m = t.match(/^舍身(?:\s*[:：]\s*(近战|远程|法术|all))?\s*$/))) { entry.data.sheshenTarget = m[1] || 'all'; continue; }
      if ((m = t.match(/^召唤\s*[:：]\s*(.+)$/))) { entry.data.summonTarget = m[1].trim(); continue; }
      if (t === '他人') { entry.data.isOthers = true; continue; }
      if (t === '必中') { entry.data.guaranteedHit = true; continue; }
      if (t === '转火') { entry.data.switchTarget = true; continue; }
      if (t === '高阶') { entry.data.isHighTier = true; continue; }
      if (t === '传奇' || t === '神术') { entry.data.isLegendary = true; continue; }
      if (t === '近战' || t === '远程' || t === '法术') { entry.data.damageType = t; continue; }
      if ((m = t.match(/^特效\s*[:：]\s*(.+)$/))) { entry.data.fxTag = m[1].trim(); continue; }
      if ((m = t.match(/^肃正\s*[:：]\s*(.+)$/))) { entry.data.barrierSub = m[1].trim(); continue; }
      // 裸效果槽（无 power，兜底 20）与冒号简写效果槽
      const colon = t.match(/^(.+?)\s*[:：]\s*(\d+)$/);
      const base = colon ? colon[1].trim() : t;
      if (SLOT_NAMES.indexOf(base) >= 0 &amp;&amp; slot < 3) {
        slot++;
        entry.data[slot === 1 ? 'type' : 'type' + slot] = '[' + base + ']';
        entry.data[slot === 1 ? 'power' : 'power' + slot] = colon ? parseInt(colon[2], 10) : 20;
      }
