  // 物品行解析：标签体系镜像 RpgCombat parseItem（类别/数量/次数/绑定），效果槽留待战斗端 YAML 提供
  function parseItemLine(raw, entry) {
    const nm = raw.match(/【([^】]+)】/);
    if (!nm) return false;
    entry.data.name = nm[1].trim();
    const tags = raw.match(/\[([^\[\]]+)\]/g) || [];
    for (let i = 0; i < tags.length; i++) {
      const t = tags[i].slice(1, -1).trim();
      let m;
      if (t === '弹药' || t === '消耗品' || t === '道具') { entry.data.category = t; continue; }
      if ((m = t.match(/^数量\s*[:：]\s*(\d+)$/))) { entry.data.count = parseInt(m[1], 10); continue; }
      if ((m = t.match(/^次数\s*[:：]\s*(\d+)$/))) { entry.data.maxUses = parseInt(m[1], 10); continue; }
