        m[1].split(/[;；]/).forEach(function (seg) {
          const s = seg.trim(); if (!s) return;
          const b = s.match(/^(.*?)\s*[*×xX]\s*(\d+)$/);
          entry.data.bindings.push(b ? { skillName: b[1].trim(), cost: parseInt(b[2], 10) } : { skillName: s, cost: 1 });
        });
        continue;
      }
    }
    return true;
  }
  function parseAttrLine(s) {
    const cfg = { img: null, classType: '', isWise: false, maxHp: 0, maxMp: 0, maxTp: 100, atk: 0, def: 0, spd: 0, actCount: 1 };
    let m;
    if ((m = s.match(/\[HP\s*[:：]\s*(\d+)\s*\/\s*(\d+)\]/))) cfg.maxHp = parseInt(m[2], 10);
    if ((m = s.match(/\[MP\s*[:：]\s*(\d+)\s*\/\s*(\d+)\]/))) cfg.maxMp = parseInt(m[2], 10);
    if ((m = s.match(/\[Atk\s*[:：]\s*(\d+)\]/i))) cfg.atk = parseInt(m[1], 10);
    if ((m = s.match(/\[Armor\s*[:：]\s*(\d+)\]/i))) cfg.def = parseInt(m[1], 10);
    if ((m = s.match(/\[Speed\s*[:：]\s*(\d+)\]/i))) cfg.spd = parseInt(m[1], 10);
    if ((m = s.match(/\[(?:职业|职阶|Class|Role)\s*[:：]\s*([^\]]+)\]/i))) cfg.classType = m[1].trim();
    if ((m = s.match(/\[(?:行动次数|Act)\s*[:：]\s*(\d+)\]/i))) cfg.actCount = parseInt(m[1], 10);
    return cfg;
  }
  function parseCombatBlock(text) {
    const classes = {};
    const lines = String(text).split('\n');
    let cur = null;
    function finalize() {
      if (cur &amp;&amp; cur.className &amp;&amp; cur.config) classes[cur.className] = cur;
      cur = null;
    }
    for (let i = 0; i < lines.length; i++) {
      if (/^\s*-\s*角色\s*:\s*$/.test(lines[i])) { finalize(); cur = { className: '', config: null, skills: [], items: [], inItems: false }; continue; }
      if (!cur) continue;
      let m = lines[i].match(/^\s*名字\s*[:：]\s*"([^"]+)"\s*$/);
      if (m) { cur.className = m[1].trim(); cur.inItems = false; continue; }
      m = lines[i].match(/^\s*属性\s*[:：]\s*"([^"]+)"\s*$/);
      if (m) { cur.config = parseAttrLine(m[1]); cur.inItems = false; continue; }
      if (/^\s*技能\s*[:：]\s*$/.test(lines[i])) { cur.inItems = false; continue; }
      if (/^\s*物品\s*[:：]\s*$/.test(lines[i])) { cur.inItems = true; continue; }
      m = lines[i].match(/^\s*-\s*"(.+)"\s*$/);
      if (m) {
        if (cur.inItems) {
          const itemEntry = { id: '', data: emptyItemData() };
          if (parseItemLine(m[1], itemEntry)) {
            itemEntry.id = itemEntry.data.name;
            cur.items.push(itemEntry);
          }
          continue;
        }
        const entry = { id: '', shopCost: 1, scope: '', srcClass: '', data: emptySkillData() };
        if (parseSkillLine(m[1], entry)) {
          entry.id = entry.data.name;
          entry.srcClass = cur.className;
          entry.rawText = m[1];
          cur.skills.push(entry);
        }
      }
    }
    finalize();
    return { classes: classes, errors: [] };
  }
  function validateCombat(c) {
    const errs = [];
    ['隐匿者', '狂战士', '防守者', '风行者', '施法者', '圣职者', '灾厄使'].forEach(function (cls) {
      const cc = c.classes[cls];
      if (!cc) { errs.push('缺少职业段：' + cls); return; }
      if (cc.skills.length !== 6) errs.push(cls + ' 技能数≠6（' + cc.skills.length + '）');
      const lim = cc.skills.filter(function (s) { return s.scope === '限定'; }).length;
      const gen = cc.skills.filter(function (s) { return s.scope === '通用'; }).length;
      if (lim !== 3 || gen !== 3) errs.push(cls + ' 限定/通用 ≠ 3/3（' + lim + '/' + gen + '）');
      if (!cc.config || !cc.config.classType) errs.push(cls + ' 缺属性行');
      const skillNames = {};
      cc.skills.forEach(function (s) { skillNames[s.data.name] = 1; });
      const itemNames = {};
      (cc.items || []).forEach(function (it) {
        if (itemNames[it.data.name]) errs.push(cls + ' 物品名重复：' + it.data.name);
        itemNames[it.data.name] = 1;
        (it.data.bindings || []).forEach(function (b) {
          if (!skillNames[b.skillName]) errs.push(cls + ' 物品「' + it.data.name + '」绑定的技能不存在：' + b.skillName);
        });
      });
    });
    const seen = {};
    Object.keys(c.classes).forEach(function (cls) {
      c.classes[cls].skills.forEach(function (s) {
        if (seen[s.data.name]) errs.push('技能名重复：' + s.data.name);
        seen[s.data.name] = 1;
      });
    });
    return errs;
