  let bgmFadeTimer = null;
  function updateBgmForStage(targetStage) {
    const targetUrl = getBgmUrlForStage(targetStage);
    if (!targetUrl || !bgm) return;

    const currentSrc = bgm.src || '';
    const isSameSong = currentSrc &amp;&amp; (
      currentSrc === targetUrl ||
      currentSrc.indexOf(encodeURI(targetUrl)) >= 0 ||
      encodeURI(currentSrc).indexOf(encodeURI(targetUrl)) >= 0 ||
      currentSrc.split('?')[0].split('#')[0] === targetUrl.split('?')[0].split('#')[0]
    );

    if (isSameSong) {
      if (state.soundOn &amp;&amp; bgm.paused) {
        bgm.volume = 0.55;
        bgm.play().catch(function () { /* 静默 */ });
      } else if (!state.soundOn &amp;&amp; !bgm.paused) {
        bgm.pause();
      }
      return;
    }

    if (bgmFadeTimer) {
      clearInterval(bgmFadeTimer);
      bgmFadeTimer = null;
    }

    if (!state.soundOn) {
      bgm.pause();
      bgm.src = targetUrl;
      return;
    }

    // 平滑淡出后切换
    bgmFadeTimer = setInterval(function () {
      if (bgm.volume > 0.08) {
        bgm.volume = Math.max(0, bgm.volume - 0.08);
      } else {
        clearInterval(bgmFadeTimer);
        bgmFadeTimer = null;
        bgm.pause();
        bgm.src = targetUrl;
        bgm.volume = 0;
        bgm.play().then(function () {
