  function extractMechanicsKeys(rawText, skillName = null) {
    const keys = [];
    if (!rawText) return keys;
    if (rawText.includes('看破')) keys.push('看破');
    if (rawText.includes('反应')) keys.push('反应');
    if (rawText.includes('舍身')) keys.push('舍身');
    if (rawText.includes('反击')) keys.push('反击');
    if (rawText.includes('肃正')) keys.push('肃正');
    if (rawText.includes('免伤')) keys.push('免伤');
    if (rawText.includes('再动')) keys.push('再动');
    if (rawText.includes('延迟')) keys.push('延迟');
    if (rawText.includes('加速')) keys.push('加速');
    if (rawText.includes('眩晕')) keys.push('眩晕');
    if (rawText.includes('召唤')) keys.push('召唤');
    if (rawText.includes('单速') || rawText.includes('群速')) keys.push('单速');
    if (rawText.includes('单缓') || rawText.includes('群缓')) keys.push('目标缓速');
    if (rawText.includes('单滞') || rawText.includes('群滞') || rawText.includes('降避')) keys.push('目标降避');
    if (rawText.includes('单避') || rawText.includes('群避')) keys.push('持续闪避');
    if (rawText.includes('单盾') || rawText.includes('群盾') || rawText.includes('护盾')) keys.push('护盾吸收');
    if (rawText.includes('单降') || rawText.includes('群降') || rawText.includes('降防')) keys.push('目标降防');
    if (rawText.includes('单防') || rawText.includes('群防') || rawText.includes('加防')) keys.push('目标加防');
    if (rawText.includes('单弱') || rawText.includes('群弱') || rawText.includes('降攻')) keys.push('目标降攻');
    if (rawText.includes('单增') || rawText.includes('群增') || rawText.includes('增攻')) keys.push('目标增攻');
    if (rawText.includes('单盲') || rawText.includes('群盲') || rawText.includes('致盲')) keys.push('目标致盲');
    if (rawText.includes('单瞄') || rawText.includes('群瞄') || rawText.includes('瞄准')) keys.push('目标瞄准');
    if (rawText.includes('单冲') || rawText.includes('群冲') || rawText.includes('充能')) keys.push('战技充能');

    // 仇恨与隐匿判断：若为负仇恨或包含隐匿，提取隐匿；正仇恨提取仇恨嘲讽
    const tauntMatches = rawText.match(/\[嘲讽(?:;[^\]]*)?\]/g) || [];
    let hasTauntPositive = false;
    let hasTauntNegative = rawText.includes('隐匿');
    tauntMatches.forEach(t => {
      if (t.includes('-')) {
        hasTauntNegative = true;
      } else {
        hasTauntPositive = true;
      }
    });
    if (hasTauntNegative) keys.push('隐匿');
    if (hasTauntPositive) keys.push('仇恨嘲讽');

    if (/限\d+次|限用/.test(rawText)) keys.push('场次限制');
    if (rawText.includes('自盲') || rawText.includes('自降') || rawText.includes('自弱')) keys.push('自身致盲');
    if (rawText.includes('必中')) keys.push('必中');
    if (rawText.includes('暴击')) keys.push('暴击');
    if (rawText.includes('穿透')) keys.push('穿透');
    if (rawText.includes('散射') || rawText.includes('霰弹')) keys.push('散射');
    if (rawText.includes('转火')) keys.push('转火');
    if (rawText.includes('回避')) keys.push('回避');
    if (rawText.includes('麻痹')) keys.push('麻痹');
    if (rawText.includes('中毒')) keys.push('中毒');
    if (rawText.includes('燃烧')) keys.push('燃烧');
    if (rawText.includes('他人')) keys.push('他人');
    if (rawText.includes('驱散')) keys.push('驱散');

    // MP 以外的资源消耗说明（生命消耗、战技点消耗、弹药材料）
    if (/\[HP:\d+\]/i.test(rawText)) keys.push('生命消耗');
    if (/\[TP:\d+\]/i.test(rawText)) keys.push('战技点消耗');
    if (rawText.includes('子弹') || rawText.includes('鹿弹') || rawText.includes('道具') || rawText.includes('消耗品') || (skillName &amp;&amp; GLOBAL_AMMO_BINDINGS[skillName])) {
      keys.push('材料绑定');
    }

    return Array.from(new Set(keys));
  }

  /* 具有持续生效时间的机制列表与其匹配标签正则 */
  const DURATION_MECH_PATTERNS = {
    '目标致盲': [/^(?:单盲|群盲|致盲)/i],
    '自身致盲': [/^(?:自盲|自降|自弱)/i],
    '目标降防': [/^(?:单降|群降|降防)/i],
    '目标加防': [/^(?:单防|群防|加防)/i],
    '目标降攻': [/^(?:单弱|群弱|降攻)/i],
    '目标增攻': [/^(?:单增|群增|增攻)/i],
    '目标缓速': [/^(?:单缓|群缓|缓速)/i],
    '单速': [/^(?:单速|群速|加速)/i],
    '目标降避': [/^(?:单滞|群滞|降避)/i],
    '持续闪避': [/^(?:单避|群避|闪避)/i],
    '护盾吸收': [/^(?:单盾|群盾|护盾)/i],
    '目标瞄准': [/^(?:单瞄|群瞄|瞄准)/i],
    '隐匿': [/^(?:隐匿)/i],
    '仇恨嘲讽': [/^(?:嘲讽)/i],
    '中毒': [/^(?:中毒|群中毒)/i],
    '燃烧': [/^(?:燃烧|群燃烧)/i],
    '麻痹': [/^(?:麻痹|群麻痹)/i],
    '眩晕': [/^(?:眩晕|击晕)/i],
    '延迟': [/^(?:延迟)/i]
  };

  /* 获取特定机制或效果在指定技能中的生效回合数（瞬发或被动规则返回 null） */
  function getMechTurns(mechKey, rawText, matchedTagStr = null) {
    if (!mechKey || !DURATION_MECH_PATTERNS[mechKey]) return null;

    let targetTag = matchedTagStr;
    if (!targetTag &amp;&amp; rawText) {
      const tags = rawText.match(/\[([^\]]+)\]/g) || [];
      for (const t of tags) {
        const inner = t.slice(1, -1).trim();
        const parts = inner.split(/[;；]/);
        const mainPart = parts[0].trim();

        if (mechKey === '隐匿') {
          if (mainPart === '隐匿' || (mainPart.includes('嘲讽') &amp;&amp; parts.some(p => p.includes('-')))) {
            targetTag = inner;
            break;
          }
        } else if (mechKey === '仇恨嘲讽') {
          if (mainPart.includes('嘲讽') &amp;&amp; !parts.some(p => p.includes('-'))) {
            targetTag = inner;
            break;
          }
        } else if (DURATION_MECH_PATTERNS[mechKey].some(pat => pat.test(mainPart))) {
          targetTag = inner;
          break;
        }
      }
    }

    // 1. 优先匹配该标签片段自带的 ;turns:N
    if (targetTag) {
      const tm = targetTag.match(/;turns?[:：](\d+)/i);
      if (tm) return parseInt(tm[1], 10);
    }

    // 2. 自盲专属规则：用户明确指定"自盲基本都是2回合，造雾术是和敌方debuff区分开的"
    if (mechKey === '自身致盲') return 2;

    // 3. 眩晕（跳过行动）：默认 1 回合
    if (mechKey === '眩晕') return 1;

    // 4. 延迟蓄力准备
    if (mechKey === '延迟') {
      if (targetTag) {
        const dm = targetTag.match(/延迟[:：](\d+)/i);
        if (dm) return parseInt(dm[1], 10);
      }
      return 1;
    }

    // 5. 检查全局顶级 [Turns:N] 或 [持续:N] 声明
    if (rawText) {
      const gm = rawText.match(/\[(?:Turns?|持续)[:：](\d+)/i);
      if (gm) return parseInt(gm[1], 10);
    }

    // 6. 其他持续性 Buff / Debuff 状态遵循底层引擎默认 3 回合
    return 3;
  }

  function formatSkillEffectPills(rawText) {
    if (!rawText) return '';
    let clean = rawText.replace(/【[^】]+】/, '');
    // 彻底剥离重复后台前缀
    clean = clean.replace(/\[(限定|通用)\]/g, '');
    clean = clean.replace(/\[价:\d+\]/g, '');
    clean = clean.replace(/\[MP:\d+\]/g, '');
    clean = clean.replace(/\[HP:\d+\]/g, '');
    clean = clean.replace(/\[TP:\d+\]/g, '');
    clean = clean.replace(/\[特效:[^\]]+\]/g, '');

    const hasOthers = rawText.includes('[他人]') || rawText.includes('他人');
    const targetOrSelf = hasOthers ? '目标' : '自身';

    const tagMatches = clean.match(/\[([^\]]+)\]/g) || [];
    if (tagMatches.length === 0) {
      return '<span class="text-[0.65rem] text-white/30 font-mono">无特殊效果</span>';
    }

    const pills = [];
    tagMatches.forEach(tagStr => {
      const inner = tagStr.slice(1, -1).trim();
      const parts = inner.split(/[;；]/);
      const mainPart = parts[0].trim();
      let powerVal = null;
      let extraTurns = null;
      parts.slice(1).forEach(p => {
        const pm = p.match(/power:(-?\d+)/i);
        if (pm) powerVal = pm[1];
        const tm = p.match(/turns:(\d+)/i);
        if (tm) extraTurns = tm[1];
      });

      let displayLabel = '';
      let displayVal = powerVal;

      if (/^持续[:：](\d+)/i.test(mainPart) || /^Turns?[:：](\d+)/i.test(mainPart)) {
        // 持续回合已统一移至右侧命中率之前专属时序徽章展示，左侧胶囊彻底去除以防冗余
        return;
      } else if (/^Aim[:：](\d+)/i.test(mainPart) || /^Hit[:：](\d+)/i.test(mainPart) || mainPart === '必中') {
        // 右侧状态列已专设金色命中率栏，左侧胶囊彻底去除以防冗余
        return;
      } else if (/^加速[:：](\d+)/i.test(mainPart) || /^单速[:：](\d+)/i.test(mainPart) || mainPart === '单速') {
        const m = mainPart.match(/^(?:加速|单速)[:：](\d+)/i);
        displayLabel = `${targetOrSelf}加速`;
        displayVal = m ? `+${m[1]}` : (powerVal ? `+${powerVal}` : null);
      } else if (/^单冲[:：](\d+)/i.test(mainPart) || mainPart === '单冲') {
        const m = mainPart.match(/^单冲[:：](\d+)/i);
        displayLabel = `${targetOrSelf}充能`;
        displayVal = m ? m[1] : powerVal;
      } else if (/^单瞄[:：](\d+)/i.test(mainPart) || mainPart === '单瞄') {
        const m = mainPart.match(/^单瞄[:：](\d+)/i);
        displayLabel = `${targetOrSelf}瞄准`;
        displayVal = m ? m[1] : powerVal;
      } else if (/^单防[:：](\d+)/i.test(mainPart) || mainPart === '单防') {
        const m = mainPart.match(/^单防[:：](\d+)/i);
        displayLabel = `${targetOrSelf}加防`;
        displayVal = m ? m[1] : powerVal;
      } else if (/^单避[:：](\d+)/i.test(mainPart) || mainPart === '单避') {
        const m = mainPart.match(/^单避[:：](\d+)/i);
        displayLabel = `${targetOrSelf}闪避`;
        displayVal = m ? m[1] : powerVal;
      } else if (/^单增[:：](\d+)/i.test(mainPart) || mainPart === '单增') {
        const m = mainPart.match(/^单增[:：](\d+)/i);
        displayLabel = `${targetOrSelf}增攻`;
        displayVal = m ? m[1] : powerVal;
      } else if (/^单盾[:：](\d+)/i.test(mainPart) || mainPart === '单盾') {
        const m = mainPart.match(/^单盾[:：](\d+)/i);
        displayLabel = `${targetOrSelf}护盾`;
        displayVal = m ? m[1] : powerVal;
      } else if (/^单回[:：](\d+)/i.test(mainPart) || mainPart === '单回') {
        const m = mainPart.match(/^单回[:：](\d+)/i);
        displayLabel = `${targetOrSelf}回复`;
        displayVal = m ? m[1] : powerVal;
      } else if (/^单回蓝[:：](\d+)/i.test(mainPart) || mainPart === '单回蓝') {
        const m = mainPart.match(/^单回蓝[:：](\d+)/i);
        displayLabel = `${targetOrSelf}回蓝`;
        displayVal = m ? m[1] : powerVal;
      } else if (mainPart === '嘲讽' || mainPart === '隐匿') {
        const isNeg = (powerVal != null &amp;&amp; (Number(powerVal) < 0 || String(powerVal).startsWith('-'))) || mainPart === '隐匿';
        if (isNeg) {
          displayLabel = `${targetOrSelf}隐匿`;
          displayVal = powerVal != null ? String(Math.abs(Number(powerVal))) : null;
        } else {
          displayLabel = `${targetOrSelf}嘲讽`;
          displayVal = powerVal != null ? String(powerVal) : null;
        }
      } else if (/^延迟[:：](\d+)/i.test(mainPart)) {
        const m = mainPart.match(/^延迟[:：](\d+)/i);
        displayLabel = '蓄力';
        displayVal = (m ? m[1] : '') + '回合';
      } else if (/^暴击[:：](\d+)%?/i.test(mainPart)) {
        const m = mainPart.match(/^暴击[:：](\d+)%?/i);
        displayLabel = '暴击';
        displayVal = (m ? m[1] : '') + '%';
      } else if (/^限(\d+)次/i.test(mainPart)) {
        const m = mainPart.match(/^限(\d+)次/i);
        displayLabel = '限用';
        displayVal = (m ? m[1] : '') + '次';
      } else if (/^(?:反应|舍身|看破)(?::([^\]]+))?/i.test(mainPart)) {
        // 右上角已专设金色战术机制徽章（如【⟲反应·近战】、【舍身·近战】、【看破·法术】），下方胶囊中不再重复显示
        return;
      } else if (/^肃正(?::([^\]]+))?/i.test(mainPart)) {
        const m = mainPart.match(/^肃正(?::([^\]]+))?/i);
        displayLabel = m &amp;&amp; m[1] ? `肃正·${m[1]}` : '绝对肃正';
      } else if (/^召唤(?::([^\]]+))?/i.test(mainPart)) {
        const m = mainPart.match(/^召唤(?::([^\]]+))?/i);
        displayLabel = m &amp;&amp; m[1] ? `召唤·${m[1]}` : '战术召唤';
      } else if (/^散射(?:\([^)]+\))?/i.test(mainPart)) {
        displayLabel = '散射伤害';
      } else if (/^群散射(?:\([^)]+\))?/i.test(mainPart)) {
        displayLabel = '群体散射';
      } else if (/^单体(?:\([^)]+\))?/i.test(mainPart)) {
        // 括号备注（光、火焰、枪击等）只是特效标签，技能栏统一改为【单体伤害】
        displayLabel = '单体伤害';
      } else if (/^穿透(?:\([^)]+\))?/i.test(mainPart)) {
        displayLabel = '单体穿透';
      } else if (mainPart === '他人' || mainPart === '友方' || mainPart === '友方目标') {
        displayLabel = '他人';
        displayVal = null;
      } else if (mainPart === '法术' || mainPart === '近战' || mainPart === '远程' || mainPart === '高阶' || mainPart === '传奇') {
        // 头部与阶级徽章已标注伤害属性与阶级，效果行内无需重复
        return;
      } else if (/^(群驱散|驱散)(?::(\d+))?/i.test(mainPart)) {
        const m = mainPart.match(/^(群驱散|驱散)(?::(\d+))?/i);
        const isGroup = m[1].includes('群');
        displayLabel = isGroup ? '群体净化' : '单体净化';
        displayVal = m[2] ? m[2] + '层' : null;
      } else if (TAG_EXPAND_MAP[mainPart]) {
        displayLabel = TAG_EXPAND_MAP[mainPart];
      } else {
        displayLabel = mainPart;
      }

      // 关联机制 key 用于胶囊悬停聚焦
      let targetMechKey = null;
      if (displayLabel.includes('散射')) targetMechKey = '散射';
      else if (displayLabel.includes('转火')) targetMechKey = '转火';
      else if (displayLabel.includes('肃正')) targetMechKey = '肃正';
      else if (displayLabel.includes('免伤')) targetMechKey = '免伤';
      else if (displayLabel.includes('回避')) targetMechKey = '回避';
      else if (displayLabel.includes('穿透')) targetMechKey = '穿透';
      else if (displayLabel.includes('再动') || displayLabel.includes('额外行动')) targetMechKey = '再动';
      else if (displayLabel.includes('蓄力')) targetMechKey = '延迟';
      else if (displayLabel.includes('加速')) targetMechKey = '加速';
      else if (displayLabel.includes('麻痹')) targetMechKey = '麻痹';
      else if (displayLabel.includes('中毒') || displayLabel.includes('毒素侵蚀')) targetMechKey = '中毒';
      else if (displayLabel.includes('燃烧') || displayLabel.includes('灼烧')) targetMechKey = '燃烧';
      else if (displayLabel.includes('降防')) targetMechKey = '目标降防';
      else if (displayLabel.includes('加防')) targetMechKey = '目标加防';
      else if (displayLabel.includes('降攻')) targetMechKey = '目标降攻';
      else if (displayLabel.includes('增攻')) targetMechKey = '目标增攻';
      else if (displayLabel.includes('自身致盲') || displayLabel.includes('自盲')) targetMechKey = '自身致盲';
      else if (displayLabel.includes('致盲')) targetMechKey = '目标致盲';
      else if (displayLabel.includes('缓速')) targetMechKey = '目标缓速';
      else if (displayLabel.includes('降避')) targetMechKey = '目标降避';
      else if (displayLabel.includes('瞄准')) targetMechKey = '目标瞄准';
      else if (displayLabel.includes('充能')) targetMechKey = '战技充能';
      else if (displayLabel.includes('隐匿')) targetMechKey = '隐匿';
      else if (displayLabel.includes('嘲讽')) targetMechKey = '仇恨嘲讽';
      else if (displayLabel.includes('限用') || displayLabel.includes('限次')) targetMechKey = '场次限制';
      else if (displayLabel.includes('闪避') &amp;&amp; !displayLabel.includes('紧急回避')) targetMechKey = '持续闪避';
      else if (displayLabel.includes('护盾')) targetMechKey = '护盾吸收';
      else if (displayLabel.includes('他人')) targetMechKey = '他人';
      else if (displayLabel.includes('净化')) targetMechKey = '驱散';
      else if (displayLabel.includes('反击')) targetMechKey = '反击';
      else if (displayLabel.includes('暴击')) targetMechKey = '暴击';
      else if (displayLabel.includes('必中')) targetMechKey = '必中';
      else if (displayLabel.includes('眩晕') || displayLabel.includes('击晕')) targetMechKey = '眩晕';
      else if (displayLabel.includes('召唤')) targetMechKey = '召唤';

      const mechFocusAttr = targetMechKey ? `data-mech-focus="${targetMechKey}"` : '';

      // 属性语义分类（战术全息透镜 · 毛玻璃微晶）
      let cat = 'buff';
      if (displayLabel === '他人' || displayLabel === '友方' || displayLabel === '持续' || displayLabel === '限用' || displayLabel === '蓄力') {
        cat = 'aux';
      } else if (displayLabel.includes('回复') || displayLabel.includes('回蓝') || displayLabel.includes('充能') || displayLabel.includes('净化') || displayLabel.includes('抽取') || displayLabel.includes('驱散')) {
        cat = 'heal';
      } else if (displayLabel.includes('伤害') || displayLabel.includes('穿透') || displayLabel.includes('枪击') || displayLabel.includes('散射') || displayLabel.includes('光')) {
        cat = 'damage';
      } else if (displayLabel.includes('护盾') || displayLabel.includes('加防') || displayLabel.includes('闪避') || displayLabel.includes('免伤') || displayLabel.includes('回避') || displayLabel.includes('舍身') || displayLabel.includes('肃正')) {
        cat = 'defense';
      } else if (displayLabel.includes('降防') || displayLabel.includes('降攻') || displayLabel.includes('缓速') || displayLabel.includes('致盲') || displayLabel.includes('中毒') || displayLabel.includes('燃烧') || displayLabel.includes('麻痹') || displayLabel.includes('眩晕') || displayLabel.includes('自盲') || displayLabel.includes('滞')) {
        cat = 'debuff';
      } else {
        cat = 'buff';
      }

      if (cat === 'aux') {
        // 辅助属性（他人、持续、限用、蓄力）：紧凑浅灰半透微标，无呼吸光点，低调不抢视线
        pills.push(`
          <span ${mechFocusAttr} class="pill-trigger inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[0.6rem] font-mono border border-white/5 bg-white/[0.02] text-white/40 leading-none cursor-pointer">
            <span>${esc(displayLabel)}</span>
            ${displayVal != null ? `<span class="font-bold font-mono text-white/60 ml-0.5">${esc(displayVal)}</span>` : ''}
          </span>
        `);
      } else {
        // 核心战斗收益：极细半透微晶描边 + 呼吸微光色点指示分类 + 象牙金等宽数值
        let dotClass = 'bg-amber-400 shadow-[0_0_6px_rgba(251,191,36,0.9)]';
        if (cat === 'heal') dotClass = 'bg-emerald-400 shadow-[0_0_6px_rgba(52,211,153,0.9)]';
        else if (cat === 'damage') dotClass = 'bg-rose-400 shadow-[0_0_6px_rgba(251,113,133,0.9)]';
        else if (cat === 'defense') dotClass = 'bg-sky-400 shadow-[0_0_6px_rgba(56,189,248,0.9)]';
        else if (cat === 'debuff') dotClass = 'bg-purple-400 shadow-[0_0_6px_rgba(192,132,252,0.9)]';

        pills.push(`
          <span ${mechFocusAttr} class="pill-trigger inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[0.63rem] font-mono border border-white/10 bg-white/[0.03] backdrop-blur-sm leading-none text-white/80 shadow-[inset_0_1px_0_rgba(255,255,255,0.08)] cursor-pointer">
            <span class="w-1.5 h-1.5 rounded-full ${dotClass} shrink-0"></span>
            <span class="tracking-wide">${esc(displayLabel)}</span>
            ${displayVal != null ? `<span class="font-bold text-amber-200 font-mono ml-0.5">${esc(displayVal)}</span>` : ''}
          </span>
        `);
      }
    });

    return pills.join('');
  }

  /* 技能阶级判定：普通 (Tier 1) / 高阶 (Tier 2) / 传奇 (Tier 3) */
  function getSkillTier(s) {
    if (!s) return 1;
    const text = (s.rawText || '') + ' ' + ((s.data &amp;&amp; s.data.name) || s.name || '');
    if (text.includes('[传奇]') || text.includes('传奇')) return 3;
    if (text.includes('[高阶]') || text.includes('高阶') || text.includes('净蚀反冲')) return 2;
    return 1;
  }
  /* 战技列表排序：严格按 普通(Tier 1) → 高阶(Tier 2) → 传奇(Tier 3) 阶梯升序排列（demo 同款稳定排序） */
  function getSortedHeroSkills(skills) {
    return [...skills].sort((a, b) => {
      const tierA = getSkillTier(a);
      const tierB = getSkillTier(b);
      if (tierA !== tierB) {
        return tierA - tierB;
      }
      return 0;
    });
  }

  // ---- 工具 ----
  function esc(s) {
    return String(s == null ? '' : s).split('&amp;').join('&amp;amp;').split('<').join('&amp;lt;').split('>').join('&amp;gt;').split('"').join('&amp;quot;');
  }
  function fill(tpl, map) {
    let out = tpl;
    Object.keys(map).forEach(function (k) { out = out.split('{' + k + '}').join(map[k]); });
    return out;
  }
  // ---- 职业与队伍数据 ----
  function classConfigOf(cls) {
    const cc = COMBAT.classes[cls];
    return cc ? JSON.parse(JSON.stringify(cc.config)) : null;
  }
  function classSkills(cls) {
    return (COMBAT.classes[cls] || { skills: [] }).skills;
  }
  function classItems(cls) {
    return (COMBAT.classes[cls] || { items: [] }).items;
  }
  function limitedSkills(cls) {
    return classSkills(cls).filter(function (s) { return s.scope === '限定'; });
  }
  function genericPool() {
    const pool = [];
    Object.keys(COMBAT.classes).forEach(function (cls) {
      COMBAT.classes[cls].skills.forEach(function (s) { if (s.scope === '通用') pool.push(s); });
    });
    return pool;
  }
  function hero3Name() {
    return state.hero3.name || OPENING_DATA.identity.defaultName;
  }
  function hero3PortraitUrl() {
    const p = state.hero3.customPortraits.filter(function (c) { return c.key === state.hero3.portrait; })[0];
    return (p &amp;&amp; p.url) || '';
  }
  // 属性按职业自动适配：直接取职业模板（classConfigOf 深拷贝，不污染源数据）
  function hero3Config() {
    const cfg = classConfigOf(state.hero3.classType);
    if (!cfg) return null;
    cfg.img = hero3PortraitUrl() || null;
    return cfg;
  }
  function attrLine(cfg) {
    return '[❤️HP:' + cfg.maxHp + '/' + cfg.maxHp + '][💠MP:' + cfg.maxMp + '/' + cfg.maxMp
      + '][⚔️Atk:' + cfg.atk + '][🛡️Armor:' + cfg.def + '][👟Speed:' + cfg.spd + '][🎖️职业:' + cfg.classType + ']';
  }
  function skillTagSummary(entry) {
    const d = entry.data;
    const parts = [];
    if (d.type) parts.push(d.type.replace(/[\[\]]/g, '') + (d.power ? ':' + d.power : ''));
    if (d.type2) parts.push(d.type2.replace(/[\[\]]/g, '') + (d.power2 ? ':' + d.power2 : ''));
    if (d.type3) parts.push(d.type3.replace(/[\[\]]/g, '') + (d.power3 ? ':' + d.power3 : ''));
    if (d.damageType) parts.push(d.damageType);
    if (d.isReaction) parts.push('反应' + (d.reactionTarget &amp;&amp; d.reactionTarget !== 'all' ? '·' + d.reactionTarget : '·全能'));
    if (d.cost) parts.push('MP' + d.cost);
    if (d.hpCost) parts.push('HP' + d.hpCost);
    if (d.turns) parts.push('持续' + d.turns);
    if (d.critRate) parts.push('暴击' + d.critRate + '%');
    if (d.hit < 100) parts.push('命中' + d.hit);
    return parts.join(' · ');
  }
  function itemEntries() {
    return OPENING_DATA.items.filter(function (e) { return state.selectedItems.has(e.id); });
  }
  // 弹药自动分配：职业标配物品（深拷贝）基础上，按最终 6 技能补齐耗弹绑定——
  // 已有绑定跳过；同弹种弹匣追加绑定行；无同弹种则新建弹匣（数量取 Combat_block 同名弹匣最大标配数）
  function hero3AmmoAllocation() {
    const items = classItems(state.hero3.classType).map(function (e) {
      return { id: e.id, data: JSON.parse(JSON.stringify(e.data)) };
    });
    limitedSkills(state.hero3.classType).concat(genericSkillEntries()).forEach(function (s) {
      const ab = GLOBAL_AMMO_BINDINGS[s.data.name];
      if (!ab) return; // 非耗弹技能
      const covered = items.some(function (it) {
        return (it.data.bindings || []).some(function (b) { return b.skillName === s.data.name; });
      });
      if (covered) return;
      const ammo = items.find(function (it) { return it.data.name === ab.ammoName; });
      if (ammo) {
        ammo.data.bindings.push({ skillName: s.data.name, cost: ab.count });
        return;
      }
      let stock = 0;
      Object.keys(COMBAT.classes).forEach(function (cls) {
        (COMBAT.classes[cls].items || []).forEach(function (it) {
          if (it.data.name === ab.ammoName) stock = Math.max(stock, it.data.count || 0);
        });
      });
      const entry = { id: ab.ammoName, data: emptyItemData() };
      entry.data.name = ab.ammoName;
      entry.data.category = '弹药';
      entry.data.count = stock || ab.count * 4;
      entry.data.bindings = [{ skillName: s.data.name, cost: ab.count }];
      items.push(entry);
    });
    return items;
  }
  // hero3 随身物品 = 所选职业标配物品（Combat_block 物品段）+ 自己购点的物品
  function hero3ItemEntries() {
    return hero3AmmoAllocation().concat(itemEntries());
  }
  // hero1/hero2 随身武器（纯叙事，随职业变 / 固定），走 Status_block 物品徽章，不进战斗档案
  function hero1Weapons() {
    const h1 = OPENING_DATA.party.hero1;
    return (h1.weaponsByClass &amp;&amp; h1.weaponsByClass[state.hero1Class]) || [];
  }
  function hero2Weapons() {
    return OPENING_DATA.party.hero2.fixedWeapons || [];
  }
  function itemsUsed() {
    return itemEntries().reduce(function (a, e) { return a + e.shopCost; }, 0);
  }
  function genericSkillEntries() {
    const pool = genericPool();
    return state.hero3.skills.map(function (name) {
      return pool.find(function (e) { return e.data.name === name; });
    }).filter(Boolean);
  }
  function genericSkillUsed() {
    const pool = genericPool();
    return state.hero3.skills.reduce(function (a, name) {
      const e = pool.find(function (p) { return p.data.name === name; });
      return a + (e ? e.shopCost : 0);
    }, 0);
  }
  function fmtTs(ts) {
    const d = new Date(ts);
    const p = function (n) { return (n < 10 ? '0' : '') + n; };
    return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
  }
  function listNames(entries) {
    return entries.length ? entries.map(function (e) { return '「' + e.data.name + '」'; }).join('、') : '（无）';
  }

  // ---- 打字机 ----
  function typewrite(el, text, done) {
    stopTw();
    if (window.__OPENING_DEBUG__ &amp;&amp; window.__OPENING_DEBUG__.instant) {
      el.textContent = text;
      el.classList.remove('tw-caret');
      if (done) done();
      return;
    }
    el.textContent = '';
    el.classList.add('tw-caret');
    state.twEl = el; state.twText = text; state.twDone = done;
    let i = 0;
    state.twTimer = setInterval(function () {
      i++;
      el.textContent = text.slice(0, i);
      if (i >= text.length) finishTw();
    }, 24);
  }
  function finishTw() {
    stopTw();
    if (state.twEl) state.twEl.textContent = state.twText;
    elDropCaret();
    if (state.twDone) { const d = state.twDone; state.twDone = null; d(); }
  }
  function stopTw() {
    if (state.twTimer) { clearInterval(state.twTimer); state.twTimer = null; }
  }
  function elDropCaret() {
    if (state.twEl) state.twEl.classList.remove('tw-caret');
  }

  // ---- 酒馆助手接口封装（特性检测 + 降级） ----
  const TH = {
    hasVars: function () { return typeof getVariables === 'function'; },
    hasAssign: function () { return typeof insertOrAssignVariables === 'function'; },
    hasCreateMsg: function () { return typeof createChatMessages === 'function'; },
    hasSlash: function () { return typeof triggerSlash === 'function'; },
    readChatVars: async function () {
      if (!this.hasVars()) return null;
      try { return (await getVariables({ type: 'chat' })) || null; } catch (e) { return null; }
    },
    writeChatVars: async function (payload) {
      if (!this.hasAssign()) throw new Error('酒馆助手 insertOrAssignVariables 不可用');
      await insertOrAssignVariables(payload, { type: 'chat' });
    },
    sendAssistantMessage: async function (message) {
      if (this.hasCreateMsg()) {
        await createChatMessages([{ role: 'assistant', message: message }], { insert_before: 'end' });
        return 'createChatMessages';
      }
      if (this.hasSlash()) {
        // 降级：/sendas 以角色名义发送（换行会被压平，属尽力而为的旧版兼容路径）
        await triggerSlash('/sendas name=' + hero3Name() + ' ' + message.split('\n').join(' '));
        return 'triggerSlash';
      }
      throw new Error('酒馆助手消息接口不可用（createChatMessages / triggerSlash 均未检测到）');
    },
  };

  /* ====================================================================
   * 写入链路（一次性，确认时执行；每步幂等可安全重试）
   *   1. $mms_portrait_choice     → MiniMapStatus 立绘选择
   *   2. rpg_combat_roster        → RpgCombat 英雄档案（version 1 结构）
   *   3. createChatMessages       → AI 角色开场白落楼（含立绘标签 + Status_block）
   *   4. $opening_setup_done      → 本组件幂等标记
   * ==================================================================== */

  function buildHeroSave(entry) {
    // entry: { name, emoji, url, classType, config, skills[], items[] }
    const cfg = entry.config;
    cfg.classType = entry.classType;
    cfg.img = entry.url || null;
    return {
      name: entry.name,
      config: cfg,
      skills: entry.skills.map(function (e) { return Object.assign({}, e.data); }),
      items: entry.items.map(function (e) { return Object.assign({}, e.data); }),
    };
  }

  function buildPartySave() {
    const h1 = OPENING_DATA.party.hero1;
    const h2 = OPENING_DATA.party.hero2;
    const hero1 = buildHeroSave({
      name: h1.name, url: h1.url, classType: state.hero1Class,
      config: classConfigOf(state.hero1Class) || {}, skills: classSkills(state.hero1Class), items: classItems(state.hero1Class),
    });
    const hero2 = buildHeroSave({
      name: h2.name, url: h2.url, classType: state.hero2Class,
      config: classConfigOf(state.hero2Class) || {}, skills: classSkills(state.hero2Class), items: classItems(state.hero2Class),
    });
    const hero3 = buildHeroSave({
      name: hero3Name(), url: hero3PortraitUrl(), classType: state.hero3.classType,
      config: hero3Config() || {}, skills: limitedSkills(state.hero3.classType).concat(genericSkillEntries()), items: hero3ItemEntries(),
    });
    return { version: 1, heroes: [hero1, hero2, hero3] };
  }

  // 战斗物品分类词条（RpgCombat/MMS 通道：【弹药】【消耗品】【道具】独立行，格式 [名x数量] 供 _sbParseItems 解析）
  function buildItemsOfCategory(entries, category) {
    const list = entries.filter(function (e) { return e.data.category === category; });
    if (!list.length) return '无';
    return list.map(function (e) {
      const c = e.data.count || 0;
      return '[' + e.data.name + (c > 1 ? 'x' + c : '') + ']';
    }).join('');
  }
  // 物品行=叙事物品徽章：无数量段，RpgCombat _sbParseItems 不入列，只叙事不进战斗数据
  function buildStoryBadgeString(story) {
    const parts = String(story || '').split(/[、，,;；]/).map(function (s) {
      return s.trim().replace(/[\[\]]/g, '');
    }).filter(Boolean);
    return parts.length ? parts.map(function (p) { return '[' + p + ']'; }).join('') : '无';
  }
  function buildWeaponsString(entries) {
    const weapons = entries.filter(function (e) { return e.data.category === '武器'; });
    if (!weapons.length) return '无';
    return '[🔪] ' + weapons.map(function (e) { return '[' + e.data.name + ']'; }).join('');
  }

  function buildStatusBlock() {
    const h1 = OPENING_DATA.party.hero1;
    const h2 = OPENING_DATA.party.hero2;
    const cfg3 = hero3Config();
    const roles = [
      { emoji: h1.emoji, name: h1.name, attrs: state.hero1Class ? attrLine(classConfigOf(state.hero1Class)) : '', wearing: h1.wearing, inner: h1.inner, items: classItems(state.hero1Class), story: hero1Weapons().join('、') },
      { emoji: h2.emoji, name: h2.name, attrs: state.hero2Class ? attrLine(classConfigOf(state.hero2Class)) : '', wearing: h2.wearing, inner: h2.inner, items: classItems(state.hero2Class), story: hero2Weapons().join('、') },
      { emoji: OPENING_DATA.identity.emoji, name: hero3Name(), attrs: cfg3 ? attrLine(cfg3) : '', wearing: state.hero3.wearing, inner: state.hero3.inner, items: hero3ItemEntries(), story: state.hero3.storyItems },
    ];
    const lines = [];
    lines.push('状态栏:');
    lines.push('  日期和时间: "' + OPENING_DATA.status.date + '"');
    lines.push('  地点: "' + OPENING_DATA.status.place + '"');
    lines.push('  角色列表:');
    roles.forEach(function (r) {
      lines.push('    - 角色:');
      lines.push('        名字: "' + r.emoji + r.name + '"');
      lines.push('        属性: "' + (r.attrs || '未分配') + '"');
      lines.push('        穿着: "' + r.wearing + '"');
      lines.push('        内心: "' + r.inner + '"');
      lines.push('        武器: "' + buildWeaponsString(r.items) + '"');
      // 物品=叙事徽章（只叙事）；战斗物品走【弹药】【消耗品】【道具】词条与 RpgCombat 打通
      lines.push('        物品: "' + buildStoryBadgeString(r.story) + '"');
      lines.push('        弹药: "' + buildItemsOfCategory(r.items, '弹药') + '"');
      lines.push('        消耗品: "' + buildItemsOfCategory(r.items, '消耗品') + '"');
      lines.push('        道具: "' + buildItemsOfCategory(r.items, '道具') + '"');
    });
    if (OPENING_DATA.status.allies.length || OPENING_DATA.status.npcs.length) {
      lines.push('  人物:');
      lines.push('    盟友: ' + JSON.stringify(OPENING_DATA.status.allies));
      lines.push('    NPC: ' + JSON.stringify(OPENING_DATA.status.npcs));
    }
    lines.push('  行动选项:');
    lines.push('    名字: "🧑 ' + hero3Name() + '"');
    lines.push('    选项:');
    OPENING_DATA.status.options.forEach(function (o) { lines.push('      - "' + o + '"'); });
    return '<Status_block>\n' + lines.join('\n') + '\n</Status_block>';
  }

  function buildOpeningMessage() {
    const narrative = fill(OPENING_DATA.openingTemplate, {
      名一: OPENING_DATA.party.hero1.name,
      名二: OPENING_DATA.party.hero2.name,
      名三: hero3Name(),
      职业一: state.hero1Class || '（未定）',
      职业二: state.hero2Class || '（未定）',
      职业三: state.hero3.classType || '（未定）',
      技能一: listNames(classSkills(state.hero1Class)),
      技能二: listNames(classSkills(state.hero2Class)),
      物品清单: listNames(itemEntries()),
    });
    const tags = [];
    if (OPENING_DATA.party.hero1.url) tags.push('【立绘 ' + OPENING_DATA.party.hero1.name + '】');
    if (OPENING_DATA.party.hero2.url) tags.push('【立绘 ' + OPENING_DATA.party.hero2.name + '】');
    if (hero3PortraitUrl() &amp;&amp; state.hero3.portrait) tags.push('【立绘 ' + state.hero3.portrait + '】');
    return narrative + '\n\n' + tags.join('') + '\n\n' + buildStatusBlock();
  }

  function buildDoneFlag() {
    return {
      ts: Date.now(),
      chars: [
        { slot: 'hero1', name: OPENING_DATA.party.hero1.name, classType: state.hero1Class },
        { slot: 'hero2', name: OPENING_DATA.party.hero2.name, classType: state.hero2Class },
        { slot: 'hero3', name: hero3Name(), classType: state.hero3.classType, portrait: state.hero3.portrait },
      ],
      customPortraits: state.hero3.customPortraits.slice(),
      skills: genericSkillEntries().map(function (e) { return e.data.name; }),
      items: itemEntries().map(function (e) { return e.data.name; }),
    };
  }

  // MMS 本机图片快照合并：把三个角色的 {名字: 立绘URL} 写入独立补丁键
  // openingsetup_portrait_patch_v1，由 MMS 启动时吸收进图片表并清键。不读-改-写
  // 共享键 mms_img_data_llm_v1——那会与 MMS 的整表落盘形成 last-write-wins 竞态，
  // 并发时丢一方更新；各写各的键后双写消除。存储不可用时静默跳过
  //（玩家可在 MMS 图片管理里手动添加）。
  function mergeMmsPortraitSnapshot() {
    const maps = [
      { key: OPENING_DATA.party.hero1.name, url: OPENING_DATA.party.hero1.url },
      { key: OPENING_DATA.party.hero2.name, url: OPENING_DATA.party.hero2.url },
      { key: state.hero3.portrait, url: hero3PortraitUrl() },
    ].filter(function (m) { return m.key &amp;&amp; m.url; });
    if (!maps.length) return;
    try {
      const KEY = 'openingsetup_portrait_patch_v1';
      let patch;
      try { patch = JSON.parse(localStorage.getItem(KEY)); } catch (e) { patch = null; }
      if (!patch || typeof patch !== 'object' || !patch.portrait || typeof patch.portrait !== 'object') {
        patch = { v: 1, portrait: {} };
      }
      maps.forEach(function (m) { patch.portrait[m.key] = m.url; });
      localStorage.setItem(KEY, JSON.stringify(patch));
    } catch (e) { /* 存储不可用：跳过 */ }
  }

  async function submitAll() {
    if (state.submitting) return;
    state.submitting = true;
    state.stage = 'loading';
    state.progress = 0;
    state.stepRows = [];
    render();

    const steps = [
      ['立绘选择同步 · MiniMapStatus', async function () {
        if (state.hero3.portrait) await TH.writeChatVars({ $mms_portrait_choice: state.hero3.portrait });
        mergeMmsPortraitSnapshot();
      }],
      ['战斗档案写入 · RpgCombat', async function () {
        await TH.writeChatVars({ rpg_combat_roster: buildPartySave() });
      }],
      ['开场白以 AI 角色身份注入聊天流', async function () {
        if (state.openingSent) return; // 重试时防重复落楼
        await TH.sendAssistantMessage(buildOpeningMessage());
        state.openingSent = true;
      }],
      ['归档标记写入', async function () {
        await TH.writeChatVars({ $opening_setup_done: buildDoneFlag() });
      }],
    ];

    try {
      for (let i = 0; i < steps.length; i++) {
        state.stepRows.push({ label: steps[i][0], status: 'run' });
        renderLoading();
        await steps[i][1]();
        state.stepRows[i].status = 'ok';
        state.progress = Math.round(((i + 1) / steps.length) * 100);
        renderLoading();
      }
      state.stage = 'done';
      render();
    } catch (err) {
      state.submitting = false;
      state.errorMsg = (err &amp;&amp; err.message) || String(err);
      state.stage = 'error';
      render();
    }
  }

  /* ==================== 渲染 ==================== */

  function bgLayers() { return ''; } // 背景层为静态 DOM，不随阶段重绘

  function render() {
    stopTw();
    document.body.className = (state.stage === 'c2') ? 'theme-gilded' : 'theme-arcane';
    let html = '';
    switch (state.stage) {
      case 'title': html = viewTitle(); break;
      case 'story': html = viewStory(); break;
      case 'c1': html = viewC1(); break;
      case 'c2': html = viewC2(); break;
      case 'c3id': html = viewC3id(); break;
      case 'c3class': html = viewC3class(); break;
      case 'c3skill': html = viewC3skill(); break;
      case 'c3item': html = viewItems(); break;
      case 'confirm': html = viewConfirm(); break;
      case 'loading': html = viewLoading(); break;
      case 'done': html = viewDone(); break;
      case 'archived': html = viewArchived(); break;
      case 'error': html = viewError(); break;
      default: html = viewTitle(); break;
    }
    app.innerHTML = html;
    afterRender();
    preheatCombatGifs(state.stage);
    updateDockBgmUi();
    updateTopRulesVisibility();
    if (state.soundOn) {
      if (state.stage === 'c1') playHeroCurrentVoice('hero1');
      else if (state.stage === 'c2') playHeroCurrentVoice('hero2');
      else voiceAudio.pause();
    }
    updateBgmForStage(state.stage);
  }

  function renderLoading() {
    // 只更新进度区，避免整屏重绘闪烁
    const box = document.getElementById('loading-body');
    if (box) { box.innerHTML = loadingBody(); return; }
    render();
  }

  function afterRender() {
    const twEl = document.querySelector('[data-tw]');
    if (twEl) {
      typewrite(twEl, twEl.getAttribute('data-tw'), function () {
        const nxt = document.getElementById('tw-next');
        if (nxt) nxt.classList.remove('hidden');
      });
    }
    const nameInput = document.getElementById('name-input');
    if (nameInput) {
      nameInput.addEventListener('input', function () { state.hero3.name = nameInput.value.trim() || OPENING_DATA.identity.defaultName; });
    }
    const wearingInput = document.getElementById('wearing-input');
    if (wearingInput) {
      wearingInput.addEventListener('input', function () { state.hero3.wearing = wearingInput.value.trim() || OPENING_DATA.identity.wearing; });
    }
    const innerInput = document.getElementById('inner-input');
    if (innerInput) {
      innerInput.addEventListener('input', function () { state.hero3.inner = innerInput.value.trim() || OPENING_DATA.identity.inner; });
    }
    const storyItemsInput = document.getElementById('story-items-input');
    if (storyItemsInput) {
      storyItemsInput.addEventListener('input', function () { state.hero3.storyItems = storyItemsInput.value.trim(); });
    }
    const urlInput = document.getElementById('custom-purl');
    if (urlInput) {
      urlInput.addEventListener('input', function () {
        const prev = document.getElementById('custom-preview');
        if (!prev) return;
        const v = urlInput.value.trim();
        if (/^https?:\/\//.test(v)) {
          prev.onerror = function () { prev.classList.add('hidden'); };
          prev.src = v;
          prev.classList.remove('hidden');
        }
        else { prev.removeAttribute('src'); prev.classList.add('hidden'); }
      });
    }
  }

