      + '<h2 class="text-2xl md:text-3xl font-black tracking-[0.25em] text-[#e8dcc0] flicker">' + esc(title) + '</h2>'
      + '<div class="mx-auto mt-3 w-24 h-px" style="background:linear-gradient(90deg,transparent,var(--amber-dim),transparent)"></div>'
