  /* 技能插槽芯片渲染（支持低饱和微透胶囊流） */
  /* ===== demo 移植：技能芯片美化全套（类型 emoji / 命中率 / 反应徽章 / 主题化芯片） ===== */
  /* 技能类型判定：近战(⚔️)、远程(🏹)、法术(🔮)、战术(♟️) */
  function getSkillTypeEmoji(s) {
    if (!s) return '✦';
    const text = (s.rawText || '') + ' ' + ((s.data &amp;&amp; s.data.name) || '');
    if (text.includes('法术')) return '🔮';
    if (text.includes('近战')) return '⚔️';
    if (text.includes('远程')) return '🏹';
    return '♟️';
  }
  function getSkillTypeTitle(s) {
    if (!s) return '战技';
    const text = (s.rawText || '') + ' ' + ((s.data &amp;&amp; s.data.name) || '');
    if (text.includes('法术')) return '法术';
    if (text.includes('近战')) return '近战';
    if (text.includes('远程')) return '远程';
    return '战术';
  }
  /* 命中率判定（源数据已解析 data.hit/guaranteedHit，"自身"类增益沿用 demo 的 rawText 判定） */
  function getSkillAimText(s) {
    if (!s) return '100%';
    const d = s.data || {};
    const text = (s.rawText || '') + ' ' + (d.name || '');
    if (d.guaranteedHit || text.includes('必中')) return '必中';
    if (d.hit &amp;&amp; d.hit !== 100) return d.hit + '%';
    if (text.includes('[单盾]') || text.includes('[群回]') || text.includes('[单回]') || text.includes('[回避]') || text.includes('[单避]') || text.includes('肃正') || text.includes('单盾') || text.includes('单防')) {
      return '自身';
    }
    return '100%';
  }
  /* 特殊战术机制徽章文本（反应带⟲，舍身与看破独立显示如 舍身·近战、看破·法术） */
  function getReactionBadgeText(s) {
    if (!s) return null;
    const text = (s.rawText || '') + ' ' + ((s.data &amp;&amp; s.data.name) || '');
    const m = text.match(/\[(反应|舍身|看破)(?::([^\]]+))?\]/);
    if (!m &amp;&amp; !(s.data &amp;&amp; s.data.isReaction)) return null;
    const act = m ? m[1] : '反应';
    const limit = (m &amp;&amp; m[2]) ? m[2].trim() : null;
    if (act === '反应') {
      return limit ? `⟲反应·${limit}` : '⟲反应·全能';
    }
    return limit ? `${act}·${limit}` : act;
  }

  /* 渲染：技能芯片卡片（主题角标框 + 品阶动效 + 右侧消耗列与命中率展示） */
  function renderSkillSlotChip(s, isSlotEmpty, slotIdx, canRemove, heroTheme) {
    if (isSlotEmpty || !s) {
      return '<div class="skill-slot-chip border-dashed border-opacity-40" style="--slot-idx:' + slotIdx + '; border-color:var(--slot-border); background:rgba(0,0,0,0.3);">'
        + '<div class="flex items-center gap-3">'
        + '  <span class="w-7 h-7 rounded bg-white/5 flex items-center justify-center font-mono text-xs text-white/40">✦</span>'
        + '  <span class="text-xs tracking-wider text-white/35">空置通用插槽 · 待购点装配</span>'
        + '</div>'
        + '<span class="font-mono text-[0.68rem] text-white/30">[SLOT OPEN]</span>'
        + '</div>';
    }

    const d = s.data || {};
    const skillName = d.name || s.id;
    const typeEmoji = getSkillTypeEmoji(s);
    const typeTitle = getSkillTypeTitle(s);
    const aimText = getSkillAimText(s);
    const aimDisplayText = aimText === '必中' ? '必中' : (aimText === '自身' ? '自身' : '命中 ' + aimText);
    const tier = getSkillTier(s);

    let tierClass = '';
    let tierBadgeHtml = '';
    if (tier === 3) {
      tierClass = 'tier-legendary';
      tierBadgeHtml = '<span class="tier-badge-modern-leg text-[0.58rem] px-2 py-0.5 rounded-full font-mono font-bold shrink-0 flex items-center gap-1">★ 传奇</span>';
    } else if (tier === 2) {
      tierClass = 'tier-advanced';
      tierBadgeHtml = '<span class="tier-badge-modern-adv text-[0.58rem] px-2 py-0.5 rounded-full font-mono font-bold shrink-0 flex items-center gap-1">✦ 高阶</span>';
    }

    let chipClass = '';
    let badgeBoxClass = '';
    let costRightText = '';

    if (heroTheme === 'gold') {
      // 威廉：专属金色主题（四角星 + 金色光晕，右侧显示命中率）
      chipClass = 'theme-gold';
      badgeBoxClass = 'border-amber-500/60 bg-amber-950/40 text-amber-300 shadow-[0_0_8px_rgba(217,180,92,0.3)]';
      costRightText = '<span class="text-amber-300/85 font-mono text-[0.66rem] flex items-center justify-end gap-1"><span class="text-amber-400 text-xs">✦</span> ' + aimDisplayText + '</span>';
    } else if (heroTheme === 'purple') {
      // 冯：金紫交辉炼金秘术风格
      chipClass = 'theme-purple';
      badgeBoxClass = 'border-amber-400/65 bg-gradient-to-br from-amber-950/40 via-purple-950/50 to-purple-900/60 text-amber-300 shadow-[0_0_10px_rgba(217,180,92,0.35)]';
      costRightText = '<span class="text-amber-300/85 font-mono text-[0.66rem] flex items-center justify-end gap-1"><span class="text-amber-400 text-xs">✦</span> ' + aimDisplayText + '</span>';
    } else {
      // 主角：技能插槽
      chipClass = s.scope === '限定' ? 'type-limited' : 'type-generic';
      badgeBoxClass = s.scope === '限定'
        ? 'border-amber-500/50 bg-amber-950/30 text-amber-300 shadow-[0_0_6px_rgba(217,180,92,0.25)]'
        : 'border-purple-500/50 bg-purple-950/30 text-purple-300 shadow-[0_0_6px_rgba(192,132,252,0.25)]';
      costRightText = s.scope === '限定'
        ? '<span class="text-amber-300/85 font-mono text-[0.66rem] flex items-center justify-end gap-1"><span class="text-amber-400 text-xs">✦</span> ' + aimDisplayText + '</span>'
        : '<span class="font-mono text-[0.62rem] text-white/50 flex items-center justify-end gap-1"><span class="text-purple-400 text-xs">✦</span> ' + aimDisplayText + ' · ' + s.shopCost + ' 点</span>';
    }

    const ammo = GLOBAL_AMMO_BINDINGS[skillName] || null;
    const costs = [];
    if (d.cost) costs.push(d.cost + ' MP');
    if (d.hpCost) costs.push(d.hpCost + ' HP');
    if (d.tpCost) costs.push(d.tpCost + ' TP');
    if (ammo) costs.push(ammo.ammoName + '*' + ammo.count);
    const costText = costs.length > 0 ? costs.join(' / ') : '无消耗';

    // 反应类型限制徽章（如 [反应:近战] -> ⟲反应·近战）
    const reactionBadgeText = getReactionBadgeText(s);
    const reactionBadge = reactionBadgeText
      ? '<span class="text-[0.58rem] px-1.5 py-0.5 rounded font-mono shrink-0 bg-amber-950/40 border border-amber-500/40 text-amber-300 shadow-[0_0_6px_rgba(217,180,92,0.2)]">' + reactionBadgeText + '</span>'
      : '';

    // 技能类型角标（战术/远程等）：微晶半透样式
    const typeTag = d.isReaction ? '反应' : (d.damageType || '战术');
    const typeTagHtml = typeTag !== '反应'
      ? '<span class="text-[0.6rem] px-1.5 py-0.5 rounded border border-white/10 bg-white/[0.03] text-white/45 font-mono tracking-wider shrink-0">' + typeTag + '</span>'
      : '';

    const removeBtn = canRemove
      ? '<button data-action="c3-skill-remove" data-skill="' + esc(skillName) + '" class="text-xs text-rose-400/80 hover:text-rose-300 p-1 rounded hover:bg-rose-950/40 transition-colors" title="卸下芯片">✕</button>'
      : '';

    return '<div class="skill-slot-chip ' + chipClass + ' ' + tierClass + '" style="--slot-idx:' + slotIdx + '" data-skill-name="' + esc(skillName) + '" data-skill-raw="' + (s.rawText ? esc(s.rawText) : '') + '">'
      + '<div class="flex items-center gap-2.5 min-w-0 flex-1">'
      + '  <div class="w-7 h-7 rounded ' + badgeBoxClass + ' border flex items-center justify-center shrink-0">'
      + '    <span class="text-xs select-none" title="' + typeTitle + '">' + typeEmoji + '</span>'
      + '  </div>'
      + '  <div class="min-w-0 flex-1">'
      + '    <div class="flex items-center gap-1.5 truncate">'
      + '      <span class="text-xs sm:text-sm font-bold tracking-wider text-[var(--text-main)] truncate">' + esc(skillName) + '</span>'
      + tierBadgeHtml
      + reactionBadge
      + typeTagHtml
      + '    </div>'
      + '    <div class="flex items-center gap-1 flex-wrap mt-0.5">'
      + formatSkillEffectPills(s.rawText || skillName)
      + '    </div>'
      + '  </div>'
      + '</div>'
      + '<div class="flex items-center gap-2 shrink-0">'
      + '  <div class="text-right">'
      + '    <div class="font-mono text-[0.72rem] font-bold text-[var(--accent)] whitespace-nowrap">' + esc(costText) + '</div>'
      + '    <div class="font-mono text-[0.62rem] text-white/40">' + costRightText + '</div>'
      + '  </div>'
      + removeBtn
      + '</div>'
      + '</div>';
  }

  function classCard(cls, slot, picked) {
    const info = OPENING_DATA.classIntro[cls] || { intro: '', passive: '' };
    const cfg = classConfigOf(cls);
    const skills = classSkills(cls).map(function (s) {
      const lim = s.scope === '限定';
      return '<div data-skill-name="' + esc(s.data.name) + '" data-skill-raw="' + esc(s.rawText || s.data.name) + '">'
        + '<div class="flex items-baseline justify-between gap-2">'
        + '<span class="text-[0.7rem] text-[#e8dcc0]">'
        + (lim ? '<span class="text-[rgba(198,161,84,0.95)]">[限定]</span> ' : '<span class="text-[rgba(150,190,150,0.95)]">[通用]</span> ')
        + esc(s.data.name)
        + (s.data.isReaction ? ' <span class="text-[rgba(217,140,140,0.95)]">⟲反应·全能</span>' : '')
        + '</span>'
        + '<span class="font-tw text-[0.62rem] text-[rgba(198,161,84,0.6)] shrink-0">' + (lim ? '随职业' : s.shopCost + ' 点') + '</span>'
        + '</div>'
        + '<div class="mt-0.5">' + formatSkillEffectPills(s.rawText || s.data.name) + '</div>'
        + '</div>';
    }).join('');
    return '<div class="class-tab-card ' + (picked ? 'active' : '') + '" data-action="' + (slot === 'c3' ? 'c3-class-pick' : slot + '-pick') + '" data-class="' + esc(cls) + '" data-class-tab="' + esc(cls) + '">'
      + '<div class="flex items-baseline justify-between mb-1">'
      + '<span class="text-[#e8dcc0] font-bold tracking-[0.12em]">' + esc(cls) + '</span>'
      + '<span class="font-tw text-[0.64rem] text-[rgba(198,161,84,0.75)] text-right">' + esc(info.passive) + '</span>'
      + '</div>'
      + '<div class="text-xs text-[rgba(232,220,192,0.62)] leading-relaxed mb-2">' + esc(info.intro) + '</div>'
      + '<div class="font-tw text-[0.6rem] text-[rgba(198,161,84,0.65)] mb-2 break-all">' + esc(cfg ? attrLine(cfg) : '') + '</div>'
      + '<div class="border-t border-[rgba(198,161,84,0.15)] pt-2 flex flex-col gap-1">' + skills + '</div>'
      + '</div>';
  }

  function viewC1() {
    const hero = OPENING_DATA.party.hero1;
