      return '<div class="class-tab-card ' + (active ? 'active' : '') + '" data-action="c1-pick" data-class="' + esc(cName) + '" data-class-tab="' + esc(cName) + '">'
        + '<div>'
        + '  <div class="flex items-center justify-between mb-1.5">'
        + '    <h3 class="text-sm font-bold text-[var(--text-main)] tracking-wide">' + esc(cName) + '</h3>'
        + '    <span class="font-tw text-[0.65rem] px-1.5 py-0.5 rounded bg-black/40 border border-white/10 text-[var(--accent)] font-bold">' + esc(info.role || '战术') + '</span>'
        + '  </div>'
