    const skillChips = getSortedHeroSkills(skills).map(function (s, idx) { return renderSkillSlotChip(s, false, idx + 1, false, 'gold'); }).join('');

    return '<div class="min-h-screen max-w-[1560px] w-full mx-auto pl-3 sm:pl-6 pr-3 sm:pr-6 py-2 [@media(max-height:800px)]:pt-16 flex flex-col justify-center">'
      + '<div class="grid lg:grid-cols-12 gap-5 items-stretch view-transition-in">'
