      + '        <div>'
      + '          <div class="flex items-center gap-2">'
      + '            <span class="font-tw text-xs text-[var(--accent)] tracking-widest">PARTY 1 / 3</span>'
      + '            <span class="font-tw text-xs text-white/35 tracking-widest">/ CHARACTER DOSSIER</span>'
      + '          </div>'
      + '          <h2 class="text-xl font-bold tracking-wider text-[var(--text-main)] mt-0.5">选择登场职业与战技配置</h2>'
      + '        </div>'
      + '        <div class="text-right">'
      + '          <div class="font-tw text-xs font-bold text-[var(--accent)]">WILLIAM TELL</div>'
      + '          <div class="font-tw text-[0.65rem] text-white/40 mt-0.5">' + esc(hero.title || '') + '</div>'
      + '        </div>'
      + '      </div>'
      + '      <div class="grid sm:grid-cols-3 gap-2.5 mb-3">' + classCards + '</div>'
      + '      <div class="mt-2">'
      + '        <div class="flex items-center justify-between mb-1.5">'
      + '          <span class="font-tw text-xs tracking-wider text-[var(--text-muted)]">EQUIPPED SKILL SLOTS (6/6)</span>'
      + '          <span class="font-tw text-xs text-[var(--accent)]">[ 6 CLASS COMBAT ARTS ]</span>'
      + '        </div>'
      + '        <div class="flex flex-col gap-1.5 smooth-fade-transition" id="hero-skill-chips-container">' + skillChips + '</div>'
      + '      </div>'
      + '    </div>'
      + (state.flash ? '<div class="flash-warn mt-3">' + esc(state.flash) + '</div>' : '')
      + '    <div class="pt-2.5 mt-2.5 border-t border-white/10 flex items-center justify-between">'
