  /* 职业切换：局部精准淡入淡出（立绘展台框架保持稳定不动） */
  function switchHeroClassLocally(heroKey, newClass) {
    const hero = OPENING_DATA.party[heroKey];
    if (!hero) return;

    if (heroKey === 'hero1') state.hero1Class = newClass;
    else state.hero2Class = newClass;

    const clsObj = COMBAT.classes[newClass];
    const cfg = clsObj ? clsObj.config : { maxHp: 100, maxMp: 40, atk: 12, def: 3, spd: 100 };
    const voiceData = (hero.classVoiceMap &amp;&amp; hero.classVoiceMap[newClass]) || { quote: '', audioUrl: '' };

    // 1. 职业选项卡高亮增量切换
    document.querySelectorAll('[data-class-tab]').forEach(function (tab) {
      tab.classList.toggle('active', tab.getAttribute('data-class-tab') === newClass);
    });

    // 2. 左侧台词气泡平滑过渡
    const quoteEl = document.getElementById('hero-dialogue-quote');
    if (quoteEl) {
      quoteEl.style.opacity = '0';
      quoteEl.style.transform = 'translateY(4px)';
      setTimeout(function () {
        quoteEl.textContent = voiceData.quote;
        quoteEl.style.opacity = '1';
        quoteEl.style.transform = 'translateY(0)';
      }, 150);
    }

    // 3. 五维属性面板平滑更新
    const attrTitle = document.getElementById('hero-attr-profile-tag');
    if (attrTitle) attrTitle.textContent = 'PROFILE // ' + newClass;

    const attrs = [
      { id: 'hero-attr-hp', val: cfg.maxHp },
      { id: 'hero-attr-mp', val: cfg.maxMp },
      { id: 'hero-attr-atk', val: cfg.atk },
      { id: 'hero-attr-armor', val: cfg.def },
      { id: 'hero-attr-speed', val: cfg.spd },
    ];
    attrs.forEach(function (item) {
      const el = document.getElementById(item.id);
      if (el) {
        el.style.opacity = '0.2';
        setTimeout(function () {
          el.textContent = item.val;
          el.style.opacity = '1';
        }, 120);
      }
    });

    // 4. 右侧 6 技能栏重新渲染并依次阶梯滑入
    const skillsContainer = document.getElementById('hero-skill-chips-container');
    if (skillsContainer &amp;&amp; clsObj) {
      const heroTheme = heroKey === 'hero2' ? 'purple' : 'gold';
      skillsContainer.style.opacity = '0';
      skillsContainer.style.transform = 'translateY(6px)';
      setTimeout(function () {
        skillsContainer.innerHTML = getSortedHeroSkills(clsObj.skills).map(function (s, idx) {
          return renderSkillSlotChip(s, false, idx + 1, false, heroTheme);
        }).join('');
        skillsContainer.style.opacity = '1';
        skillsContainer.style.transform = 'translateY(0)';
      }, 150);
    }

    // 5. 播放专属台词音频
    playHeroCurrentVoice(heroKey);
  }

