  /* 通用技能装配与纯增量局部更新（绝不刷新整页 DOM） */
  function incrementalUpdateC3Skill(skillName, isAdded) {
    const maxPoints = OPENING_DATA.shop.skillPoints;
    const usedPoints = genericSkillUsed();
    const remainPoints = maxPoints - usedPoints;
    const pct = Math.min(100, Math.round((usedPoints / maxPoints) * 100));

    // 1. 增量更新已装配槽位
    const slotsGrid = document.getElementById('c3-equipped-slots-grid');
    if (slotsGrid) {
      slotsGrid.innerHTML = renderC3SlotsHtml();
      slotsGrid.classList.remove('slot-chip-pop');
      void slotsGrid.offsetWidth;
      slotsGrid.classList.add('slot-chip-pop');
    }

    // 2. 增量更新点数与进度条
    const remainEl = document.getElementById('c3-remain-points');
    if (remainEl) {
      remainEl.textContent = remainPoints + ' / ' + maxPoints + ' 点';
      remainEl.className = 'font-bold ' + (remainPoints === 0 ? 'text-amber-400' : 'text-[var(--accent)]');
    }

    const energyFill = document.getElementById('c3-energy-fill');
    if (energyFill) {
      energyFill.style.width = pct + '%';
    }

    // 3. 增量更新被点击卡片的选中高亮态
    const cardEl = document.querySelector('[data-skill-card="' + skillName + '"]');
    if (cardEl) {
      cardEl.classList.toggle('selected', isAdded);
    }

    // 4. 增量更新底部装配计数
    const countEl = document.getElementById('c3-equipped-count');
    if (countEl) {
      countEl.textContent = '通用槽已装配: ' + state.hero3.skills.length + '/3';
    }
  }

