    const d = e.data;
    const parts = [];
    if (d.type) parts.push(d.type.replace(/[\[\]]/g, '') + (d.power ? ':' + d.power : ''));
    if (d.type2) parts.push(d.type2.replace(/[\[\]]/g, '') + (d.power2 ? ':' + d.power2 : ''));
    if (d.type3) parts.push(d.type3.replace(/[\[\]]/g, '') + (d.power3 ? ':' + d.power3 : ''));
    if (d.isOthers) parts.push('他人');
    if (d.hit &amp;&amp; d.hit !== 100) parts.push('命中' + d.hit);
    if (d.turns) parts.push('持续' + d.turns);
    return parts.join(' · ');
