  /* 跨阶段导航：柔和沉浸淡出淡入转场（250ms 淡出 + 300ms 淡入），支持 instant 测试。
     幕布式转场：STAGE_FX 命中的目标阶段改走全屏幕布（百叶/浓雾），全闭瞬间换内容。 */
  let isStageTransitioning = false;
  const FX_TIMING = {
    blind: { close: 800, hold: 140, open: 800 },
    fog:   { close: 1050, hold: 260, open: 1150 }
  };
  const STAGE_FX = { c1: 'blind', confirm: 'fog' };

  function gotoStageWithCrossfade(st) {
    if (isStageTransitioning) return;
    if (state.stage === st) return;

    if (window.__OPENING_DEBUG__ &amp;&amp; window.__OPENING_DEBUG__.instant) {
      state.stage = st;
      render();
      return;
    }

    const fx = STAGE_FX[st];
    if (fx) {
      const ov = document.querySelector('.fx-ov[data-fx="' + fx + '"]');
      if (ov) {
        const t = FX_TIMING[fx];
        isStageTransitioning = true;
        ov.style.display = 'block';
        ov.classList.add('is-closing');
        setTimeout(function () {
          ov.classList.remove('is-closing');
          ov.classList.add('is-closed');   /* 全闭钉住，观众看不见的时刻换内容 */
          state.stage = st;
          render();
          /* 等一帧 paint 后再开帘：rAF + setTimeout(0) 保证 is-closed 先绘制；
             恶劣环境（iframe 非聚焦，rAF 可能被暂停）由 setTimeout 兜底，避免转场永久卡死 */
          let opened = false;
          const openCurtain = function () {
            if (opened) return;
            opened = true;
            ov.classList.remove('is-closed');
            ov.classList.add('is-opening');
            setTimeout(function () {
              ov.classList.remove('is-opening');
              ov.style.display = 'none';
              isStageTransitioning = false;
            }, t.open);
          };
          requestAnimationFrame(function () { setTimeout(openCurtain, 0); });
          setTimeout(openCurtain, 90);
        }, t.close);
        return;
      }
    }

    isStageTransitioning = true;
    app.classList.remove('stage-fade-in');
    app.classList.add('stage-fade-out');

    setTimeout(function () {
      state.stage = st;
      render();
      app.classList.remove('stage-fade-out');
      app.classList.add('stage-fade-in');

      setTimeout(function () {
        app.classList.remove('stage-fade-in');
        isStageTransitioning = false;
      }, 300);
    }, 250);
  }

  /* ==================== 事件 ==================== */

  app.addEventListener('click', function (ev) {
    const t = ev.target.closest('[data-action]');
    if (!t) return;
    const act = t.getAttribute('data-action');
    switch (act) {
      case 'tw-skip':
        if (state.twTimer) finishTw();
        break;
      case 'sound': enterImmersiveFs(); toggleSound(); break;
      case 'start':
        enterImmersiveFs();
        state.storyPage = 0;
        gotoStageWithCrossfade('story');
        break;
      case 'auto-fs-toggle':
        state.autoFullscreen = !state.autoFullscreen; render(); break;
      case 'story-next':
        state.storyPage++; render(); break;
      case 'story-done':
        gotoStageWithCrossfade('c1'); break;
      case 'c1-pick':
        switchHeroClassLocally('hero1', t.getAttribute('data-class') || '');
        state.flash = '';
        break;
      case 'c1-done':
        if (!state.hero1Class) { state.flash = '先为角色一选择职业'; render(); break; }
        state.flash = '';
        gotoStageWithCrossfade('c2');
        break;
      case 'c2-pick':
        switchHeroClassLocally('hero2', t.getAttribute('data-class') || '');
        state.flash = '';
        break;
      case 'c2-done':
        if (!state.hero2Class) { state.flash = '先为角色二选择职业'; render(); break; }
        state.flash = '';
        gotoStageWithCrossfade('c3id');
        break;
      case 'c3id-done':
        gotoStageWithCrossfade('c3class');
        break;
      case 'c3-class-pick':
        switchHero3ClassLocally(t.getAttribute('data-class') || '');
        state.flash = '';
        break;
      case 'c3class-done':
        if (!state.hero3.classType) { state.flash = '先为自定义角色选择职业'; render(); break; }
        state.flash = '';
        gotoStageWithCrossfade('c3skill');
        break;
      case 'c3-skill-remove':
      case 'c3-skill-toggle':
        toggleC3Skill(t.getAttribute('data-skill'));
        break;
      case 'c3skill-done':
        gotoStageWithCrossfade('c3item');
        break;
      case 'item-toggle':
        toggleItem(t.getAttribute('data-item-id'));
        break;
      case 'rules-modal':
        toggleBattleRulesModal();
        break;
      case 'c3item-done':
        gotoStageWithCrossfade('confirm');
        break;
      case 'play-voice': {
        const heroId = t.getAttribute('data-hero');
        if (heroId) playHeroCurrentVoice(heroId);
        break;
      }
      case 'portrait-pick':
        state.hero3.portrait = t.getAttribute('data-portrait-key') || ''; render(); break;
      case 'portrait-add': addCustomPortrait(); break;
      case 'confirm-submit': submitAll(); break;
      case 'retry': state.stage = 'loading'; state.stepRows = []; state.progress = 0; submitAll(); break;
      case 'force-redo':
        state.openingSent = false;
        state.doneFlag = null;
        gotoStageWithCrossfade('title');
        break;
      case 'back-c1': gotoStageWithCrossfade('c1'); break;
      case 'back-c2': gotoStageWithCrossfade('c2'); break;
      case 'back-c3id': gotoStageWithCrossfade('c3id'); break;
      case 'back-c3class': gotoStageWithCrossfade('c3class'); break;
      case 'back-c3skill': gotoStageWithCrossfade('c3skill'); break;
      case 'back-c3item': gotoStageWithCrossfade('c3item'); break;
    }
  });

  function addCustomPortrait() {
    const nameEl = document.getElementById('custom-pname');
    const urlEl = document.getElementById('custom-purl');
    const flash = document.getElementById('custom-flash');
    const name = (nameEl &amp;&amp; nameEl.value.trim()) || '自定义立绘';
    const url = urlEl ? urlEl.value.trim() : '';
    if (!/^https?:\/\//.test(url)) {
      if (flash) flash.classList.remove('hidden');
      return;
    }
    if (flash) flash.classList.add('hidden');
    // 同名覆盖：重填即修正，无需删除入口
    state.hero3.customPortraits = state.hero3.customPortraits.filter(function (p) { return p.key !== name; });
    state.hero3.customPortraits.push({ key: name, name: name, desc: '玩家自定义', url: url });
    state.hero3.portrait = name;
    render();
  }

  function toggleFs() {
    try {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else if (document.documentElement.requestFullscreen) {
        document.documentElement.requestFullscreen();
      }
    } catch (e) { /* 宿主 iframe 未授权全屏时静默 */ }
  }

  // 修仙开局同款：首屏勾选"同时开启沉浸全屏"后，点击进入/声音时自动请求全屏
  function enterImmersiveFs() {
    if (!state.autoFullscreen) return;
    try {
      if (!document.fullscreenElement &amp;&amp; document.documentElement.requestFullscreen) {
        const p = document.documentElement.requestFullscreen();
        if (p &amp;&amp; p.catch) p.catch(function () { /* 宿主拒绝时静默 */ });
      }
    } catch (e) { /* 未授权全屏时静默 */ }
  }

  function updateFsIcon() {
    const expand = document.getElementById('fs-icon-expand');
    const compress = document.getElementById('fs-icon-compress');
    if (!expand || !compress) return;
    const fs = !!document.fullscreenElement;
    expand.classList.toggle('hidden', fs);
    compress.classList.toggle('hidden', !fs);
  }

  function toggleSound() {
    state.soundOn = !state.soundOn;
    try {
      bgVideo.muted = !state.soundOn;
      updateBgmForStage(state.stage);
    } catch (e) { /* 自动播放策略拒绝时静默 */ }
    // 开启声音的瞬间预热职业语音：从标题页到威廉/艾娃界面尚有阅读时间，缓存足够就绪
    if (state.soundOn) { preloadHeroVoices('hero1'); preloadHeroVoices('hero2'); }
    // 纯状态切换：只定点刷新声音 UI，绝不整页重绘
    updateDockBgmUi();
  }

  function refreshBudget(boxId, used, total) {
    const box = document.getElementById(boxId);
    if (box) box.innerHTML = budgetBar(used, total, false);
  }

  function toggleC3Skill(name) {
    const entry = genericPool().find(function (e) { return e.data.name === name; });
    if (!entry) return;
    const idx = state.hero3.skills.indexOf(name);
    let isAdded = false;
    if (idx >= 0) {
      state.hero3.skills.splice(idx, 1);
      isAdded = false;
    } else {
      if (state.hero3.skills.length >= 3) {
        showFlashToast('通用技能槽位已满（最多装配 3 个）');
        return;
      }
      if (genericSkillUsed() + entry.shopCost > OPENING_DATA.shop.skillPoints) {
        showFlashToast('通用技能点数不足（上限 ' + OPENING_DATA.shop.skillPoints + ' 点）');
        return;
      }
      state.hero3.skills.push(name);
      isAdded = true;
    }
    // 纯增量更新：绝不触发整页 DOM 重绘，消除生硬刷新
    incrementalUpdateC3Skill(name, isAdded);
  }

  function toggleItem(id) {
    const entry = OPENING_DATA.items.find(function (e) { return e.id === id; });
    if (!entry) return;
    const totalPoints = OPENING_DATA.shop.itemPoints;
    if (state.selectedItems.has(id)) {
      state.selectedItems.delete(id);
    } else {
      if (itemsUsed() + entry.shopCost > totalPoints) {
        showFlashToast('物品预算不足（上限 ' + totalPoints + ' 点）');
        refreshBudget('item-budget', itemsUsed(), totalPoints);
        return;
      }
      state.selectedItems.add(id);
    }
    // 纯增量更新：局部刷新顶部能量条与被点击卡片高亮，绝不整页重绘
    refreshBudget('item-budget', itemsUsed(), totalPoints);
    const cardEl = document.querySelector('[data-item-id="' + id + '"]');
    if (cardEl) {
      cardEl.classList.toggle('sel', state.selectedItems.has(id));
    }
  }

  /* ==================== demo 移植：实机战斗视窗 / 技能悬浮窗 / 规则弹窗 ==================== */

  /* 悬停职业卡 → 左侧展台实机战斗视窗（仅 hover 时弹出，移开隐藏；GIF 已预热秒显） */
  function showCombatPreview(cName) {
    const info = OPENING_DATA.classIntro[cName] || {};
    const gifSrc = info.gifUrl || '';
    const monitor = document.getElementById('stage-combat-monitor');
    const img = document.getElementById('stage-combat-img');
    /* 相同职业重复悬浮不重设 src，避免动画重启与重复解码 */
    if (img &amp;&amp; gifSrc &amp;&amp; img.getAttribute('src') !== gifSrc) {
      img.src = gifSrc;
    }
    if (monitor) monitor.classList.add('active');
  }
  function hideCombatPreview() {
    const monitor = document.getElementById('stage-combat-monitor');
    if (!monitor) return;
    monitor.classList.remove('active');
    /* 弹出过渡(220ms)结束后清空 src，停止隐藏态 GIF 的持续解码播放 */
    setTimeout(function () {
      if (!monitor.classList.contains('active')) {
        const img = document.getElementById('stage-combat-img');
        if (img) img.removeAttribute('src');
      }
    }, 260);
  }
  function initCombatMonitorHover() {
    app.addEventListener('mouseover', function (ev) {
      const tab = ev.target.closest('[data-class-tab]');
      if (tab) showCombatPreview(tab.getAttribute('data-class-tab'));
    });
    app.addEventListener('mouseout', function (ev) {
      const tab = ev.target.closest('[data-class-tab]');
      if (!tab) return;
      const rel = ev.relatedTarget;
      if (rel &amp;&amp; tab.contains(rel)) return;
      hideCombatPreview();
    });
  }

  /* 进入职业步时预热当前角色名下的职业 GIF（幂等去重；仅 c1/c2 有展台视窗，c3class 无立绘展台不预热） */
  const PREHEATED_GIFS = new Set();
  function preheatCombatGifs(stage) {
    let clsNames = [];
    if (stage === 'c1' &amp;&amp; OPENING_DATA.party.hero1) clsNames = OPENING_DATA.party.hero1.classes || [];
    else if (stage === 'c2' &amp;&amp; OPENING_DATA.party.hero2) clsNames = OPENING_DATA.party.hero2.classes || [];
    clsNames.forEach(function (cName) {
      const info = OPENING_DATA.classIntro[cName];
      if (info &amp;&amp; info.gifUrl &amp;&amp; !PREHEATED_GIFS.has(info.gifUrl)) {
        PREHEATED_GIFS.add(info.gifUrl);
        const pre = new Image();
        pre.src = info.gifUrl;
      }
    });
  }

