  let currentRuleIndex = 0;

  function renderRuleTabs() {
    const bar = document.getElementById('rule-tabs-bar');
    if (!bar) return;
    const titles = ['时序', '阵型', '行动', 'TP', '指令', '控制', '侦测', '战力'];
    bar.innerHTML = RULE_CARDS.map(function (card, idx) {
      const stateCls = idx === currentRuleIndex ? 'active' : 'text-white/60 hover:text-white hover:bg-white/5';
      return `
      <button data-rule-index="${idx}"
              class="rule-tab-pill px-2.5 py-1 rounded-lg text-xs font-mono flex items-center gap-1 ${stateCls}"
              title="${card.title}">
        <span class="font-bold">${String(idx + 1).padStart(2, '0')}</span>
        <span class="hidden md:inline text-[0.68rem] opacity-80">${titles[idx]}</span>
      </button>`;
    }).join('');
  }

  function renderRuleCard() {
    const stage = document.getElementById('rule-card-stage');
    const pageInd = document.getElementById('rule-page-indicator');
    const prevBtn = document.getElementById('rule-prev-btn');
    const nextBtn = document.getElementById('rule-next-btn');
    if (!stage) return;

    const card = RULE_CARDS[currentRuleIndex];
    if (!card) return;

    // 更新 Tab 索引条
    renderRuleTabs();

    // 更新页码指示与上一项/下一项按钮态
    if (pageInd) pageInd.textContent = `${currentRuleIndex + 1} / ${RULE_CARDS.length}`;
    if (prevBtn) {
      prevBtn.disabled = currentRuleIndex === 0;
      prevBtn.style.opacity = currentRuleIndex === 0 ? '0.4' : '1';
      prevBtn.style.pointerEvents = currentRuleIndex === 0 ? 'none' : 'auto';
    }
    if (nextBtn) {
      if (currentRuleIndex === RULE_CARDS.length - 1) {
        nextBtn.innerHTML = '<span>完成阅读 · 返回战场 ✓</span>';
        nextBtn.className = 'px-4 py-1.5 rounded-lg border border-emerald-500/60 bg-emerald-500/25 hover:bg-emerald-500/40 text-emerald-200 hover:text-white transition-all cursor-pointer flex items-center gap-1 text-xs font-bold shadow-[0_0_16px_rgba(16,185,129,0.35)]';
      } else {
        nextBtn.innerHTML = '<span>下一项</span><span>▶</span>';
        nextBtn.className = 'px-4 py-1.5 rounded-lg border border-amber-500/50 bg-amber-500/20 hover:bg-amber-500/30 text-amber-200 hover:text-amber-100 transition-all cursor-pointer flex items-center gap-1 text-xs font-bold shadow-[0_0_12px_rgba(245,158,11,0.2)]';
      }
    }

    const headerBlock = `
          <!-- 头部标题 -->
          <div class="pb-2 border-b border-white/10">
            <div class="flex items-center justify-between gap-2 mb-1">
              <div class="flex items-center gap-2">
                <span class="font-mono text-xs px-2 py-0.5 rounded bg-amber-500/20 text-amber-300 border border-amber-500/30">卡片 ${String(card.id).padStart(2, '0')}</span>
                <span class="text-xs font-mono text-white/50">${card.tag}</span>
              </div>
              <span class="text-[0.65rem] font-mono text-white/40 tracking-wider">${card.subTitle}</span>
            </div>
            <h2 class="text-lg sm:text-xl font-bold text-amber-200 font-serif tracking-wide">${card.title}</h2>
            <p class="text-xs text-amber-100/80 mt-1 leading-relaxed bg-black/35 p-2 rounded-lg border-l-2 border-amber-400/80">
              ${card.desc}
            </p>
          </div>`;

    // 拆图上限用 px（酒馆 iframe 流式 vh 回归）；wide=单栏全宽大图，默认=双栏窄列图
    const imgTag = `
              <img src="${card.img}"
                   alt="${card.imgAlt}"
                   class="${card.layout === 'wide' ? 'max-w-full max-h-[340px] w-auto mx-auto' : 'max-h-[320px] w-auto'} object-contain rounded-lg transition-transform duration-300 group-hover:scale-[1.02] shadow-lg"
                   onerror="this.style.display='none'">`;

    const captionBar = `
            <div class="flex items-center justify-between px-2.5 text-[0.72rem] font-mono text-amber-300/85 bg-amber-950/20 border border-amber-500/25 rounded-lg py-1.5">
              <span class="flex items-center gap-1.5">
                <span class="text-amber-400 text-xs">🎯</span>
                <span>${card.imgCaption}</span>
              </span>
            </div>`;

    const sectionBlocks = `
          <!-- 界面说明 -->
          <div class="rule-section-block">
            <div class="flex items-center gap-1.5 text-xs font-bold text-sky-300 font-serif mb-1.5">
              <span>🔍</span><span>【界面说明】</span>
            </div>
            <ul class="space-y-1 text-xs text-white/80 leading-relaxed list-disc list-inside">
              ${card.uiPoints.map(p => `<li>${p}</li>`).join('')}
            </ul>
          </div>

          <!-- 具体机制 -->
          <div class="rule-section-block">
            <div class="flex items-center gap-1.5 text-xs font-bold text-amber-300 font-serif mb-1.5">
              <span>⚙️</span><span>【具体机制】</span>
            </div>
            <ul class="space-y-1.5 text-xs text-white/80 leading-relaxed list-disc list-inside">
              ${card.mechanics.map(m => `<li>${m}</li>`).join('')}
            </ul>
          </div>

          <!-- 实战提示 -->
          <div class="rounded-xl p-3 bg-emerald-950/30 border border-emerald-500/35 text-xs text-emerald-100 leading-relaxed shadow-sm">
            <div class="flex items-center gap-1.5 font-bold text-emerald-300 font-serif mb-1">
              <span>💡</span><span>【实战提示】</span>
            </div>
            <div class="space-y-1 text-emerald-100/90 text-xs">
              ${card.tips.map(t => `<div>${t}</div>`).join('')}
            </div>
          </div>`;

    // hero-swap-in 与角色切换同一动效，随重渲染重放
    stage.innerHTML = card.layout === 'wide' ? `
      <div class="hero-swap-in flex flex-col gap-3.5">
${headerBlock}

          <!-- 拆图图解区：全宽自适应原始比例，杜绝定高空白 -->
          <div class="flex flex-col gap-2">
            <div class="rule-img-box rounded-xl p-2 flex items-center justify-center overflow-hidden group relative w-fit min-w-[260px] max-w-full mx-auto">${imgTag}
            </div>
${captionBar}
          </div>
${sectionBlocks}
      </div>
    ` : `
      <div class="hero-swap-in grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
        <!-- 左栏：拆图图解区 -->
        <div class="lg:col-span-5 flex flex-col gap-2.5">
          <div class="rule-img-box rounded-xl p-3 flex flex-col items-center justify-center overflow-hidden group relative">${imgTag}
          </div>
${captionBar}
        </div>

        <!-- 右栏：机制详解与操作提示 -->
        <div class="lg:col-span-7 flex flex-col gap-3.5 font-sans">
${headerBlock}
${sectionBlocks}
        </div>
      </div>
    `;
  }

  function switchRuleCard(idx) {
    if (idx < 0 || idx >= RULE_CARDS.length) return;
    currentRuleIndex = idx;
    renderRuleCard();
  }

  /* 战斗规则速查弹窗交互 */
  function toggleBattleRulesModal(forceState) {
    const modal = document.getElementById('battle-rules-modal');
    if (!modal) return;
    const isVisible = modal.classList.contains('visible');
    const target = (typeof forceState === 'boolean') ? forceState : !isVisible;
    const card = modal.querySelector('.rules-modal-card');

    if (target) {
      modal.classList.add('visible');
      modal.style.opacity = '1';
      modal.style.pointerEvents = 'auto';
      if (card) card.style.transform = 'scale(1)';
      renderRuleCard(); // 打开时渲染当前卡片
    } else {
      modal.style.opacity = '0';
      modal.style.pointerEvents = 'none';
      if (card) card.style.transform = 'scale(0.95)';
      setTimeout(function () { modal.classList.remove('visible'); }, 220);
    }
  }
  function initRulesModal() {
    const modal = document.getElementById('battle-rules-modal');
    if (!modal) return;
    modal.addEventListener('click', function (ev) {
      if (ev.target.closest('[data-rules-close]')) toggleBattleRulesModal(false);
    });
    window.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') toggleBattleRulesModal(false);
    });

    // 8大卡片：Tab 索引条点击切换（事件委托，Tab 随重渲染重建）
    const tabsBar = document.getElementById('rule-tabs-bar');
    if (tabsBar) tabsBar.addEventListener('click', function (ev) {
      const pill = ev.target.closest('[data-rule-index]');
      if (pill) switchRuleCard(parseInt(pill.getAttribute('data-rule-index'), 10) || 0);
    });

    // 底栏上一项/下一项（末页变「完成阅读 · 返回战场」）
    const prevBtn = document.getElementById('rule-prev-btn');
    if (prevBtn) prevBtn.addEventListener('click', function () { switchRuleCard(currentRuleIndex - 1); });
    const nextBtn = document.getElementById('rule-next-btn');
    if (nextBtn) nextBtn.addEventListener('click', function () {
      if (currentRuleIndex < RULE_CARDS.length - 1) switchRuleCard(currentRuleIndex + 1);
      else toggleBattleRulesModal(false);
    });

    // 键盘 ←/→ 切换卡片（仅弹窗可见时接管）
    window.addEventListener('keydown', function (e) {
      const m = document.getElementById('battle-rules-modal');
      if (!m || !m.classList.contains('visible')) return;
      if (e.key === 'ArrowLeft') switchRuleCard(currentRuleIndex - 1);
      else if (e.key === 'ArrowRight') switchRuleCard(currentRuleIndex + 1);
    });

    // 右上角规则胶囊与 BGM 胶囊
    const topRulesBtn = document.getElementById('top-rules-btn');
    if (topRulesBtn) topRulesBtn.addEventListener('click', function () { toggleBattleRulesModal(true); });
    const bgmBtn = document.getElementById('bgm-toggle-btn');
    if (bgmBtn) bgmBtn.addEventListener('click', toggleSound);
  }

  /* BGM 胶囊与首屏声音按钮随声音状态同步（胶囊在 #app 外、按钮不走 render，均需手动刷） */
  function updateDockBgmUi() {
    const icon = document.getElementById('bgm-icon');
    const label = document.getElementById('bgm-label');
    if (icon) icon.textContent = state.soundOn ? '🎵' : '🔇';
    if (label) label.textContent = state.soundOn ? 'BGM' : '静音';
    const titleBtn = document.getElementById('title-sound-btn');
    if (titleBtn) titleBtn.textContent = state.soundOn ? '🔊 声音已开启' : '🔇 开启声音';
  }

  /* 右上角战斗规则速查胶囊显隐：仅战斗配置流程显示，标题页/叙事导引隐藏 */
  function updateTopRulesVisibility() {
    const btn = document.getElementById('top-rules-btn');
    if (!btn) return;
    const battleStages = ['c1', 'c2', 'c3id', 'c3class', 'c3skill', 'c3item', 'confirm'];
    btn.style.display = battleStages.indexOf(state.stage) >= 0 ? '' : 'none';
  }

  /* 纯悬浮窗（Floating Tooltip）：技能卡与机制胶囊悬停说明 */
  let activeTooltipTimer = null;

  function showTooltipForSkillData(skillName, rawText, targetRect, focusMechKey = null) {
    const tooltipContainer = document.getElementById('skill-tooltip-container');
    const ttName = document.getElementById('tt-skill-name');
    const ttIcon = document.getElementById('tt-type-icon');
    const ttBadges = document.getElementById('tt-header-badges');
    const ttBody = document.getElementById('tt-mechanics-body');

    if (!tooltipContainer) return;

    // 1. 设置头部概要
    if (ttName) ttName.textContent = skillName || '技能';

    // 从 rawText 推断类型图标与阶位标签
    let typeIcon = '⚔️';
    if (rawText &amp;&amp; rawText.includes('远程')) typeIcon = '🏹';
    else if (rawText &amp;&amp; rawText.includes('法术')) typeIcon = '🔮';
    else if (rawText &amp;&amp; rawText.includes('反应')) typeIcon = '⚡';
    if (ttIcon) ttIcon.textContent = typeIcon;

    const badges = [];
    if (rawText &amp;&amp; rawText.includes('传奇')) {
      badges.push('<span class="text-red-300 border border-red-500/50 bg-red-950/40 px-1.5 py-0.2 rounded">传奇</span>');
    } else if (rawText &amp;&amp; rawText.includes('高阶')) {
      badges.push('<span class="text-amber-300 border border-amber-500/50 bg-amber-950/40 px-1.5 py-0.2 rounded">高阶</span>');
    }
    if (rawText &amp;&amp; rawText.includes('限定')) {
      badges.push('<span class="text-amber-200/70 border border-amber-500/30 bg-black/40 px-1.5 py-0.2 rounded">限定</span>');
    } else if (rawText &amp;&amp; rawText.includes('通用')) {
      badges.push('<span class="text-purple-200/70 border border-purple-500/30 bg-black/40 px-1.5 py-0.2 rounded">通用</span>');
    }
    // 悬停特定机制图标时，回合徽章展示该机制自身的生效回合（如造雾术群盲4/自盲2）；瞬发/被动机制不展示。
    // 整卡悬浮时仅在技能显式声明顶级 [Turns:N]/[持续:N] 时展示，未声明的回合归属各机制图标自身。
    let turnsVal = null;
    if (focusMechKey) {
      turnsVal = getMechTurns(focusMechKey, rawText);
    } else {
      const topMatch = rawText ? rawText.match(/\[(?:Turns?|持续)[:：](\d+)/i) : null;
      turnsVal = topMatch ? parseInt(topMatch[1], 10) : null;
    }
    if (turnsVal != null) {
      badges.push(`<span class="text-amber-300 font-mono border border-amber-500/40 bg-amber-950/40 px-1.5 py-0.2 rounded">⏱ ${turnsVal}回合</span>`);
    }
    if (ttBadges) ttBadges.innerHTML = badges.join('');

    // 2. 提取并渲染关联机制 (按需高亮聚焦机制)
    const mechKeys = extractMechanicsKeys(rawText, skillName);
    let displayKeys = [...mechKeys];
    if (focusMechKey) {
      if (!displayKeys.includes(focusMechKey)) {
        displayKeys.unshift(focusMechKey);
      } else {
        displayKeys = [focusMechKey, ...displayKeys.filter(k => k !== focusMechKey)];
      }
    }

    // 无特殊特性机制则完全不显示悬浮窗，直接收起并返回
    if (displayKeys.length === 0) {
      hideTooltip();
      return;
    }

    if (ttBody) {
      let entriesHtml = displayKeys.map(key => {
        const item = MECHANICS_REGISTRY[key] || { title: key, icon: '✦', desc: '按标准规则结算生效。' };
        const isFocused = focusMechKey === key;
        let borderHighlight = isFocused ? 'border-amber-400/80 bg-amber-500/10' : 'border-white/5 bg-white/[0.02]';
        let titleColor = 'text-[var(--accent)]';
        let extraBadge = '';

        if (key === '生命消耗') {
          const hpM = rawText ? rawText.match(/\[HP:(\d+)\]/i) : null;
          const hpVal = hpM ? hpM[1] : '';
          borderHighlight = isFocused ? 'border-rose-400 bg-rose-950/40 shadow-[0_0_12px_rgba(244,63,94,0.3)]' : 'border-rose-500/30 bg-rose-950/20';
          titleColor = 'text-rose-300';
          if (hpVal) extraBadge = `<span class="text-[0.6rem] font-mono text-rose-300 font-bold px-1.5 py-0.2 rounded border border-rose-500/40 bg-rose-950/60 ml-auto">消耗 ${hpVal} HP</span>`;
        } else if (key === '战技点消耗') {
          const tpM = rawText ? rawText.match(/\[TP:(\d+)\]/i) : null;
          const tpVal = tpM ? tpM[1] : '';
          borderHighlight = isFocused ? 'border-sky-400 bg-sky-950/40 shadow-[0_0_12px_rgba(56,189,248,0.3)]' : 'border-sky-500/30 bg-sky-950/20';
          titleColor = 'text-sky-300';
          if (tpVal) extraBadge = `<span class="text-[0.6rem] font-mono text-sky-300 font-bold px-1.5 py-0.2 rounded border border-sky-500/40 bg-sky-950/60 ml-auto">消耗 ${tpVal} TP</span>`;
        } else if (key === '材料绑定') {
          titleColor = 'text-amber-300';
          const ammo = skillName ? GLOBAL_AMMO_BINDINGS[skillName] : null;
          if (ammo) extraBadge = `<span class="text-[0.6rem] font-mono text-amber-300 font-bold px-1.5 py-0.2 rounded border border-amber-500/40 bg-amber-950/60 ml-auto">${ammo.ammoName}*${ammo.count}</span>`;
        } else if (key === '隐匿' || key === '战术隐匿') {
          titleColor = 'text-emerald-300';
          if (isFocused) borderHighlight = 'border-emerald-400/80 bg-emerald-500/10';
        }

        const focusTurns = isFocused ? getMechTurns(key, rawText) : null;

        return `
          <div class="tooltip-mech-entry ${borderHighlight} rounded-lg px-2 py-1.5 transition-all">
            <div class="flex items-center gap-1.5 text-xs font-bold ${titleColor} mb-0.5">
              <span>${item.icon}</span>
              <span class="tracking-wide">【${item.title}】</span>
              ${extraBadge}
              ${isFocused &amp;&amp; focusTurns != null ? `<span class="text-[0.6rem] font-mono text-amber-300 font-bold px-1.5 py-0.2 rounded border border-amber-500/40 bg-amber-950/60 ml-auto shrink-0">⏱ 生效 ${focusTurns} 回合</span>` : (isFocused &amp;&amp; !extraBadge ? '<span class="text-[0.58rem] text-amber-300 font-mono font-normal ml-auto">聚焦机制</span>' : '')}
            </div>
            <div class="text-[0.72rem] text-white/80 leading-relaxed font-sans pl-5">
              ${item.desc}
            </div>
          </div>
        `;
      }).join('');

      // 若为召唤技能且涉及【化尘者】，备注化尘者的完整属性与技能档案
      if (displayKeys.includes('召唤') &amp;&amp; rawText &amp;&amp; rawText.includes('化尘者')) {
        entriesHtml += `
          <div class="mt-2 pt-2 border-t border-white/10">
            <div class="flex items-center justify-between mb-1.5">
              <span class="text-xs font-bold text-amber-300 flex items-center gap-1 font-serif">
                <span>💨</span><span>〖化尘者〗从者档案</span>
              </span>
              <span class="text-[0.58rem] font-mono text-amber-200/80 border border-amber-500/30 bg-amber-950/40 px-1.5 py-0.5 rounded">流体 · 虚形 · 1动/轮</span>
            </div>
            <div class="grid grid-cols-5 gap-1 text-[0.62rem] font-mono text-center mb-1.5 bg-black/40 p-1.5 rounded border border-white/10">
              <div><span class="text-white/40 block text-[0.52rem]">生命</span><span class="font-bold text-white/90">90</span></div>
              <div><span class="text-white/40 block text-[0.52rem]">法力</span><span class="font-bold text-sky-300">10</span></div>
              <div><span class="text-white/40 block text-[0.52rem]">攻击</span><span class="font-bold text-rose-300">45</span></div>
              <div><span class="text-white/40 block text-[0.52rem]">护甲</span><span class="font-bold text-amber-200">0</span></div>
              <div><span class="text-white/40 block text-[0.52rem]">速度</span><span class="font-bold text-emerald-300">80</span></div>
            </div>
            <div class="space-y-1 text-[0.63rem] font-mono">
              <div class="flex items-center justify-between bg-white/[0.03] px-1.5 py-0.5 rounded border border-white/5">
                <span class="text-white/90 font-bold">【沙矛】</span>
                <span class="text-white/60">单体40×2 · 命中90 · 1 MP · 近战</span>
              </div>
              <div class="flex items-center justify-between bg-white/[0.03] px-1.5 py-0.5 rounded border border-white/5">
                <span class="text-white/90 font-bold">【卷尘】</span>
                <span class="text-white/60">单体50 · 降避10+降攻10(2T) · 2 MP · 法术</span>
              </div>
              <div class="flex items-center justify-between bg-white/[0.03] px-1.5 py-0.5 rounded border border-white/5">
                <span class="text-amber-300 font-bold">【飞沙流体】</span>
                <span class="text-amber-200/70">绝对免伤40 · 反应:远程 · 2 MP</span>
              </div>
