          </div>
        `;
      }

      ttBody.innerHTML = entriesHtml;
    }

    // 3. 智能定位与防视口溢出计算
    tooltipContainer.classList.add('visible');
    const ttWidth = tooltipContainer.offsetWidth || 320;
    const ttHeight = tooltipContainer.offsetHeight || 180;
    const padding = 12;

    let posX = targetRect.left + (targetRect.width / 2) - (ttWidth / 2);
    let posY = targetRect.top - ttHeight - 8; // 默认在卡片正上方

    // 上边界溢出检测：如果上方放不下，放下方
    if (posY < padding) {
      posY = targetRect.bottom + 8;
    }
    // 左边界溢出检测
    if (posX < padding) {
      posX = padding;
    }
    // 右边界溢出检测
    if (posX + ttWidth > window.innerWidth - padding) {
      posX = window.innerWidth - ttWidth - padding;
    }

    tooltipContainer.style.left = `${Math.round(posX)}px`;
    tooltipContainer.style.top = `${Math.round(posY)}px`;
  }

  function hideTooltip() {
    const tooltipContainer = document.getElementById('skill-tooltip-container');
    if (!tooltipContainer) return;
    tooltipContainer.classList.remove('visible');
  }

  /* 全局事件委托：监听技能插槽与胶囊悬停，自适应动态重绘 */
  function initTooltipGlobalEvents() {
    const tooltipContainer = document.getElementById('skill-tooltip-container');
    let currentTrigger = null;

    document.addEventListener('mouseover', (e) => {
      // 避免在卸下按钮或悬浮窗本身上触发/闪烁
      if (e.target.closest('#skill-tooltip-container') || e.target.closest('.slot-remove-btn')) {
        return;
      }

      // 1. 优先检测是否悬停在特定的机制胶囊上
      const pill = e.target.closest('[data-mech-focus]');
      if (pill) {
        const card = pill.closest('[data-skill-name]');
        if (card) {
          currentTrigger = pill;
          clearTimeout(activeTooltipTimer);
          const skillName = card.getAttribute('data-skill-name');
          const rawText = card.getAttribute('data-skill-raw');
          const mechKey = pill.getAttribute('data-mech-focus');
          const pillRect = pill.getBoundingClientRect();
          activeTooltipTimer = setTimeout(() => {
            showTooltipForSkillData(skillName, rawText, pillRect, mechKey);
          }, 35);
          return;
        }
      }

      // 2. 检测是否悬停在技能插槽卡片或备选卡片上
      const card = e.target.closest('[data-skill-name]');
      if (card) {
        if (currentTrigger === card) return;
        currentTrigger = card;
        clearTimeout(activeTooltipTimer);
        const skillName = card.getAttribute('data-skill-name');
        const rawText = card.getAttribute('data-skill-raw');
        const cardRect = card.getBoundingClientRect();
        activeTooltipTimer = setTimeout(() => {
          showTooltipForSkillData(skillName, rawText, cardRect, null);
        }, 65);
        return;
      }
    });

    document.addEventListener('mouseout', (e) => {
      const card = e.target.closest('[data-skill-name]');
      if (card) {
        const related = e.relatedTarget;
        if (related &amp;&amp; card.contains(related)) return;
        if (related &amp;&amp; tooltipContainer &amp;&amp; tooltipContainer.contains(related)) return;

        currentTrigger = null;
        clearTimeout(activeTooltipTimer);
        hideTooltip();
      }
    });

    // 点击空白处收起
    document.addEventListener('click', (e) => {
      if (!e.target.closest('#skill-tooltip-container')) {
        clearTimeout(activeTooltipTimer);
        hideTooltip();
      }
    });

    // 页面滚动时隐藏，防止悬浮窗悬空
    window.addEventListener('scroll', () => {
      clearTimeout(activeTooltipTimer);
      hideTooltip();
    }, { passive: true });
  }

  /* ==================== 启动 ==================== */

  async function boot() {
    // 全屏按钮：独立常驻控件，不随阶段重绘
    const fsBtn = document.getElementById('fs-btn');
    if (fsBtn) fsBtn.addEventListener('click', toggleFs);
    document.addEventListener('fullscreenchange', updateFsIcon);

    // demo 移植：悬浮窗 / 实机视窗 hover / 规则弹窗的一次性事件挂载
    // （规则弹窗静态 DOM 位于主脚本之后，须等 DOM 解析完成再绑定，boot 时还是 null）
    initTooltipGlobalEvents();
    initCombatMonitorHover();
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initRulesModal);
    } else {
      initRulesModal();
    }

    // 背景视频 / BGM 配置应用
    if (OPENING_DATA.bgVideo.url) {
      bgVideo.src = OPENING_DATA.bgVideo.url;
      bgVideo.classList.remove('hidden');
      bgVideo.style.setProperty('--vid-op', String(OPENING_DATA.bgVideo.opacity || 0.6));
      bgFallback.style.display = 'none';
    }

    // 幂等检查：本聊天已初始化 → 归档摘要，不再进向导
    const vars = await TH.readChatVars();
    const done = vars ? vars.$opening_setup_done : null;
    if (done &amp;&amp; typeof done === 'object') {
      state.doneFlag = done;
      // 恢复玩家自定义立绘候选（强制重配时可复用）
      if (Array.isArray(done.customPortraits)) state.hero3.customPortraits = done.customPortraits;
      state.stage = 'archived';
    } else {
      state.stage = 'title';
    }
    render();
  }

  // 调试/测试钩子（MMS window.MMS 同款惯例，不影响产品行为）
  window.__OPENING_DEBUG__ = { state: state, DATA: OPENING_DATA, COMBAT: COMBAT, instant: false, mergeMmsPortraitSnapshot: mergeMmsPortraitSnapshot };

  boot();
})();
</script>

